-- Schema-only baseline captured from the operational project on 2026-09-13.

-- No business rows, auth accounts, sequence counters, secrets or cron jobs.

-- Apply ONLY to an empty workshop project, never to the original database.

begin;

set local check_function_bodies = off;

create schema if not exists private;

create schema if not exists extensions;

create extension if not exists pgcrypto with schema extensions;

create extension if not exists "uuid-ossp" with schema extensions;

create sequence "public"."update_notifications_id_seq" as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;

create sequence "public"."notification_views_id_seq" as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;

create sequence "public"."tipos_vehiculo_id_seq" as integer increment by 1 minvalue 1 maxvalue 2147483647 start with 1 cache 1 no cycle;

create sequence "public"."vehiculos_registrados_id_seq" as integer increment by 1 minvalue 1 maxvalue 2147483647 start with 1 cache 1 no cycle;

create sequence "public"."facturas_electronicas_id_seq" as integer increment by 1 minvalue 1 maxvalue 2147483647 start with 1 cache 1 no cycle;

create sequence "public"."clientes_fiscales_id_seq" as integer increment by 1 minvalue 1 maxvalue 2147483647 start with 1 cache 1 no cycle;

create sequence "public"."formato_folio_seq" as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;

create sequence "public"."abono_folio_seq" as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1 cache 1 no cycle;

