CREATE OR REPLACE FUNCTION public.actualizar_debe_on_precio_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Comprobamos si el precio de la factura realmente ha cambiado
  IF NEW.precio_factura IS DISTINCT FROM OLD.precio_factura THEN
    -- Calculamos el total de abonos realizados hasta el momento
    -- TotalAbonos = PrecioAnterior - DebeAnterior
    DECLARE
      total_abonos NUMERIC;
    BEGIN
      total_abonos := OLD.precio_factura - OLD.debe;

      -- Recalculamos el nuevo valor de 'debe'
      -- NuevoDebe = NuevoPrecio - TotalAbonos
      NEW.debe := NEW.precio_factura - total_abonos;
    END;
  END IF;

  -- Devolvemos la fila modificada para que la operación de UPDATE continúe
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid()
    AND role = 'admin'
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.search_formatos_globales(search_term text)
 RETURNS SETOF formatos_globales
 LANGUAGE sql
AS $function$
  SELECT * FROM formatos_globales
  WHERE
    id::text ILIKE ('%' || search_term || '%') OR
    placa::text ILIKE ('%' || search_term || '%') OR
    marca::text ILIKE ('%' || search_term || '%') OR
    cliente::text ILIKE ('%' || search_term || '%') OR
    modelo::text ILIKE ('%' || search_term || '%')
  ORDER BY fecha DESC
  LIMIT 100;
$function$
;

CREATE OR REPLACE FUNCTION public.clear_weekly_labor_goal(p_start_date date, p_end_date date)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_current_user_admin() then
    raise exception 'Solo un administrador puede eliminar la meta semanal';
  end if;

  delete from public.weekly_settlement_goals
  where period_start = p_start_date
    and period_end = p_end_date;

  return found;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.crear_o_actualizar_factura_desde_formato(p_formato_folio text)
 RETURNS TABLE(id_factura integer, id_formato_factura text, precio_total_factura numeric, debe_factura numeric, estado_factura text, cliente_factura text)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_total_repuestos NUMERIC;
    v_mano_de_obra NUMERIC;
    v_gran_total NUMERIC;
    v_cliente_nombre TEXT;
    v_factura_existente_id INT;
BEGIN
    -- 1. Calcular el costo total de los repuestos usando la columna correcta 'costo_total_linea'.
    SELECT COALESCE(SUM(costo_total_linea), 0) INTO v_total_repuestos
    FROM public.repuestos
    WHERE id_repuesto = p_formato_folio;

    -- 2. Obtener el costo de mano de obra y el nombre del cliente.
    SELECT COALESCE(costo_mano_obra, 0), nombre_cliente INTO v_mano_de_obra, v_cliente_nombre
    FROM public.formatos
    WHERE folio = p_formato_folio;

    -- 3. Calcular el gran total.
    v_gran_total := v_total_repuestos + v_mano_de_obra;

    -- 4. Actualizar la tabla de formatos con los costos calculados.
    UPDATE public.formatos
    SET costo_repuestos = v_total_repuestos, costo_total = v_gran_total
    WHERE folio = p_formato_folio;

    -- 5. Verificar si ya existe una factura para este formato.
    SELECT id INTO v_factura_existente_id
    FROM public.facturas
    WHERE id_formato = p_formato_folio;

    -- 6. Si la factura existe, actualizarla. Si no, crearla.
    IF v_factura_existente_id IS NOT NULL THEN
        UPDATE public.facturas
        SET precio_factura = v_gran_total, debe = v_gran_total - COALESCE(pagado, 0)
        WHERE id = v_factura_existente_id;
    ELSE
        INSERT INTO public.facturas (id_formato, precio_factura, debe, estado, cliente, pagado)
        VALUES (p_formato_folio, v_gran_total, v_gran_total, 'PENDIENTE', v_cliente_nombre, 0);
    END IF;

    -- 7. Devolver los datos de la factura.
    RETURN QUERY
    SELECT id, id_formato, precio_factura, debe, estado, cliente
    FROM public.facturas
    WHERE id_formato = p_formato_folio;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.actualizar_costo_total()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Calcular automáticamente el costo_total como suma de mano_obra + repuestos
    NEW.costo_total := COALESCE(NEW.costo_mano_obra, 0) + COALESCE(NEW.costo_repuestos, 0);

    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        -- En caso de error, registrar en logs pero no interrumpir la operación
        RAISE WARNING 'Error al actualizar costo_total para formato %: %', NEW.folio, SQLERRM;
        -- Intentar calcular de nuevo con valores por defecto
        NEW.costo_total := COALESCE(NEW.costo_mano_obra, 0) + COALESCE(NEW.costo_repuestos, 0);
        RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.offline_json_fields_match(p_current jsonb, p_expected jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select coalesce(bool_and(p_current -> item.key = item.value), true)
  from jsonb_each(coalesce(p_expected, '{}'::jsonb)) as item;
$function$
;

CREATE OR REPLACE FUNCTION private.apply_offline_mutation(p_operation_id uuid, p_kind text, p_entity_key text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_kind text := lower(trim(coalesce(p_kind, '')));
  v_payload_hash text;
  v_receipt public.offline_mutation_receipts;
  v_current jsonb;
  v_result jsonb;
  v_data jsonb;
  v_base jsonb;
  v_id uuid;
  v_format_operation_id uuid;
  v_catalog_operation_id uuid;
  v_folio text;
  v_name text;
  v_item jsonb;
  v_resolved jsonb;
  v_allowed_format_fields constant text[] := array[
    'nombre_cliente', 'telefono_contacto', 'placa', 'marca', 'modelo',
    'tipo_vehiculo', 'kilometraje', 'trabajos_realizados', 'observaciones',
    'costo_mano_obra', 'nombre_conductor', 'clave_control', 'fecha_salida',
    'fotos_vehiculo', 'referido_por', 'tipo_formato'
  ];
begin
  if v_user_id is null then
    raise exception 'Usuario no autenticado' using errcode = '42501';
  end if;
  if p_operation_id is null or v_kind = '' or coalesce(p_entity_key, '') = ''
     or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'La operación offline no es válida' using errcode = '22023';
  end if;

  -- Una sola transacción puede decidir y aplicar cada operación, incluso si
  -- dos teléfonos intentan sincronizarla al mismo tiempo.
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id::text, 0));
  v_payload_hash := md5(v_kind || '|' || p_entity_key || '|' || p_payload::text);

  select * into v_receipt
  from public.offline_mutation_receipts
  where operation_id = p_operation_id;

  if found then
    if v_receipt.user_id <> v_user_id
       or v_receipt.payload_hash <> v_payload_hash then
      raise exception 'El identificador de sincronización ya pertenece a otro cambio'
        using errcode = '22023';
    end if;
    return jsonb_build_object(
      'status', 'already_applied',
      'operation_id', p_operation_id,
      'result', v_receipt.result
    );
  end if;

  if v_kind = 'format.create' then
    v_data := coalesce(p_payload -> 'data', '{}'::jsonb);
    if jsonb_typeof(v_data) <> 'object' then
      raise exception 'El formato pendiente no es válido' using errcode = '22023';
    end if;
    -- Las altas pasan siempre por esta operación (también cuando hay red).
    -- Así, si el teléfono pierde la respuesta, el mismo operation_id recupera
    -- el recibo y nunca vuelve a crear el formato.
    v_result := public.create_new_format(v_data);

  elsif v_kind = 'format.update' then
    v_format_operation_id := nullif(
      p_payload ->> 'format_operation_id', ''
    )::uuid;
    if v_format_operation_id is not null then
      select receipt.result into v_resolved
      from public.offline_mutation_receipts as receipt
      where receipt.operation_id = v_format_operation_id
        and receipt.user_id = v_user_id
        and receipt.mutation_kind = 'format.create';
      if v_resolved is null then
        return jsonb_build_object(
          'status', 'deferred',
          'message', 'Primero debe sincronizarse la creación del formato.'
        );
      end if;
      v_id := nullif(v_resolved ->> 'id', '')::uuid;
    else
      v_id := nullif(p_payload ->> 'id', '')::uuid;
    end if;
    v_data := coalesce(p_payload -> 'data', '{}'::jsonb);
    v_base := coalesce(p_payload -> 'base', '{}'::jsonb);
    if v_id is null or jsonb_typeof(v_data) <> 'object' then
      raise exception 'La edición del formato no es válida' using errcode = '22023';
    end if;
    if exists (
      select 1 from jsonb_object_keys(v_data) as field
      where field <> all(v_allowed_format_fields)
    ) then
      raise exception 'La edición contiene campos no permitidos'
        using errcode = '22023';
    end if;

    select to_jsonb(formato) into v_current
    from public.formatos as formato
    where formato.id = v_id and formato.deleted_at is null
    for update;

    if v_current is null then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'El formato ya no existe o fue eliminado.'
      );
    end if;

    if public.offline_json_fields_match(v_current, v_data) then
      v_result := v_current;
    elsif jsonb_object_length(v_base) > 0
          and not public.offline_json_fields_match(v_current, v_base) then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'Otra persona cambió este formato mientras estabas offline.',
        'server', v_current,
        'local', v_data
      );
    else
      update public.formatos as formato
      set
        nombre_cliente = case when v_data ? 'nombre_cliente'
          then nullif(trim(v_data ->> 'nombre_cliente'), '') else nombre_cliente end,
        telefono_contacto = case when v_data ? 'telefono_contacto'
          then nullif(trim(v_data ->> 'telefono_contacto'), '') else telefono_contacto end,
        placa = case when v_data ? 'placa'
          then upper(nullif(trim(v_data ->> 'placa'), '')) else placa end,
        marca = case when v_data ? 'marca'
          then nullif(trim(v_data ->> 'marca'), '') else marca end,
        modelo = case when v_data ? 'modelo'
          then nullif(v_data ->> 'modelo', '')::numeric else modelo end,
        tipo_vehiculo = case when v_data ? 'tipo_vehiculo'
          then nullif(trim(v_data ->> 'tipo_vehiculo'), '') else tipo_vehiculo end,
        kilometraje = case when v_data ? 'kilometraje'
          then nullif(v_data ->> 'kilometraje', '')::numeric else kilometraje end,
        trabajos_realizados = case when v_data ? 'trabajos_realizados'
          then nullif(trim(v_data ->> 'trabajos_realizados'), '') else trabajos_realizados end,
        observaciones = case when v_data ? 'observaciones'
          then nullif(trim(v_data ->> 'observaciones'), '') else observaciones end,
        costo_mano_obra = case when v_data ? 'costo_mano_obra'
          then coalesce(nullif(v_data ->> 'costo_mano_obra', '')::numeric, 0)
          else costo_mano_obra end,
        nombre_conductor = case when v_data ? 'nombre_conductor'
          then nullif(trim(v_data ->> 'nombre_conductor'), '') else nombre_conductor end,
        clave_control = case when v_data ? 'clave_control'
          then nullif(trim(v_data ->> 'clave_control'), '') else clave_control end,
        fecha_salida = case when v_data ? 'fecha_salida'
          then nullif(v_data ->> 'fecha_salida', '')::date else fecha_salida end,
        fotos_vehiculo = case when v_data ? 'fotos_vehiculo'
          then coalesce(v_data -> 'fotos_vehiculo', '{}'::jsonb) else fotos_vehiculo end,
        referido_por = case when v_data ? 'referido_por'
          then nullif(trim(v_data ->> 'referido_por'), '') else referido_por end,
        tipo_formato = case when v_data ? 'tipo_formato'
          then nullif(trim(v_data ->> 'tipo_formato'), '') else tipo_formato end
      where id = v_id and deleted_at is null
      returning to_jsonb(formato) into v_result;
    end if;

    if nullif(trim(v_result ->> 'placa'), '') is not null
       and nullif(trim(v_result ->> 'marca'), '') is not null
       and nullif(trim(v_result ->> 'tipo_vehiculo'), '') is not null then
      insert into public.vehiculos_registrados(placa, marca, tipo_vehiculo)
      select
        upper(trim(v_result ->> 'placa')),
        trim(v_result ->> 'marca'),
        trim(v_result ->> 'tipo_vehiculo')
      where not exists (
        select 1 from public.vehiculos_registrados
        where upper(trim(placa)) = upper(trim(v_result ->> 'placa'))
      )
      on conflict do nothing;
    end if;

  elsif v_kind in (
    'format.ready',
    'format.reopen_ready',
    'format.reopen_finalized',
    'format.soft_delete',
    'format.restore',
    'format.deletion_request'
  ) then
    v_format_operation_id := nullif(
      p_payload ->> 'format_operation_id', ''
    )::uuid;
    if v_format_operation_id is not null then
      select receipt.result into v_resolved
      from public.offline_mutation_receipts as receipt
      where receipt.operation_id = v_format_operation_id
        and receipt.user_id = v_user_id
        and receipt.mutation_kind = 'format.create';
      if v_resolved is null then
        return jsonb_build_object(
          'status', 'deferred',
          'message', 'Primero debe sincronizarse la creación del formato.'
        );
      end if;
      v_id := nullif(v_resolved ->> 'id', '')::uuid;
    else
      v_id := nullif(p_payload ->> 'id', '')::uuid;
    end if;

    select to_jsonb(formato) into v_current
    from public.formatos as formato
    where formato.id = v_id
    for update;
    if v_current is null then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'El formato ya no existe.'
      );
    end if;
    v_folio := nullif(trim(v_current ->> 'folio'), '');

    if v_kind = 'format.ready' then
      if v_current ->> 'estado' = 'LISTO' then
        v_result := v_current;
      elsif v_current ->> 'estado' <> coalesce(p_payload ->> 'base_estado', 'ACTIVO')
            or (
              p_payload ? 'base_labor'
              and v_current -> 'costo_mano_obra'
                  is distinct from p_payload -> 'base_labor'
            ) then
        return jsonb_build_object(
          'status', 'conflict',
          'message', 'El formato cambió antes de marcarlo como listo.',
          'server', v_current
        );
      else
        select to_jsonb(ready_format) into v_result
        from public.mark_format_ready(v_id) as ready_format;
      end if;

    elsif v_kind in ('format.reopen_ready', 'format.reopen_finalized') then
      if v_current ->> 'estado' = 'ACTIVO' then
        v_result := v_current;
      elsif v_current ->> 'estado' <> p_payload ->> 'base_estado' then
        return jsonb_build_object(
          'status', 'conflict',
          'message', 'El estado del formato cambió antes de reabrirlo.',
          'server', v_current
        );
      elsif v_kind = 'format.reopen_finalized' then
        select to_jsonb(reopened_format) into v_result
        from public.reopen_finalized_format(
          v_id, p_payload ->> 'reason'
        ) as reopened_format;
      else
        select to_jsonb(reopened_format) into v_result
        from public.reopen_ready_format(
          v_id, p_payload ->> 'reason'
        ) as reopened_format;
      end if;

    elsif v_kind = 'format.soft_delete' then
      if v_current -> 'deleted_at' <> 'null'::jsonb then
        v_result := v_current;
      elsif v_current ->> 'estado' <> p_payload ->> 'base_estado' then
        return jsonb_build_object(
          'status', 'conflict',
          'message', 'El formato cambió antes de enviarlo a la papelera.',
          'server', v_current
        );
      else
        update public.servicios
        set deleted_at = now(), deleted_by = v_user_id
        where deleted_at is null and formato_folio in (
          v_current ->> 'folio', v_current ->> 'clave_key'
        );
        update public.repuestos
        set deleted_at = now(), deleted_by = v_user_id
        where deleted_at is null and (
          id_repuesto in (v_current ->> 'folio', v_current ->> 'clave_key')
          or formato_folio in (v_current ->> 'folio', v_current ->> 'clave_key')
        );
        update public.formatos as formato
        set deleted_at = now(), deleted_by = v_user_id,
            deletion_requested = false
        where formato.id = v_id
        returning to_jsonb(formato) into v_result;
      end if;

    elsif v_kind = 'format.restore' then
      update public.servicios
      set deleted_at = null, deleted_by = null, deletion_requested = false
      where formato_folio in (
        v_current ->> 'folio', v_current ->> 'clave_key'
      );
      update public.repuestos
      set deleted_at = null, deleted_by = null, deletion_requested = false
      where id_repuesto in (v_current ->> 'folio', v_current ->> 'clave_key')
         or formato_folio in (v_current ->> 'folio', v_current ->> 'clave_key');
      update public.formatos as formato
      set deleted_at = null, deleted_by = null, deletion_requested = false
      where formato.id = v_id
      returning to_jsonb(formato) into v_result;

    else
      if coalesce((v_current ->> 'deletion_requested')::boolean, false)
         = coalesce((p_payload ->> 'requested')::boolean, false) then
        v_result := v_current;
      else
        update public.formatos as formato
        set deletion_requested = coalesce(
          (p_payload ->> 'requested')::boolean, false
        )
        where formato.id = v_id
        returning to_jsonb(formato) into v_result;
      end if;
    end if;

  elsif v_kind in ('repuesto.create', 'repuesto.create_many') then
    v_data := case
      when v_kind = 'repuesto.create_many' then p_payload -> 'items'
      else jsonb_build_array(p_payload -> 'item')
    end;
    if jsonb_typeof(v_data) <> 'array' or jsonb_array_length(v_data) = 0 then
      raise exception 'Los repuestos pendientes no son válidos'
        using errcode = '22023';
    end if;
    v_resolved := '[]'::jsonb;
    for v_item in select value from jsonb_array_elements(v_data)
    loop
      v_format_operation_id := nullif(
        v_item ->> 'format_operation_id', ''
      )::uuid;
      if v_format_operation_id is not null then
        select receipt.result into v_current
        from public.offline_mutation_receipts as receipt
        where receipt.operation_id = v_format_operation_id
          and receipt.user_id = v_user_id
          and receipt.mutation_kind = 'format.create';
        if v_current is null then
          return jsonb_build_object(
            'status', 'deferred',
            'message', 'Primero debe sincronizarse la creación del formato.'
          );
        end if;
        v_item := (v_item - 'format_operation_id') || jsonb_build_object(
          'formato_id', v_current ->> 'id',
          'formato_folio', v_current ->> 'clave_key',
          'id_repuesto', v_current ->> 'folio'
        );
      end if;
      v_catalog_operation_id := nullif(
        v_item ->> 'catalog_operation_id', ''
      )::uuid;
      if v_catalog_operation_id is not null then
        select receipt.result into v_current
        from public.offline_mutation_receipts as receipt
        where receipt.operation_id = v_catalog_operation_id
          and receipt.user_id = v_user_id
          and receipt.mutation_kind = 'catalog.create';
        if v_current is null then
          return jsonb_build_object(
            'status', 'deferred',
            'message', 'Primero debe sincronizarse el repuesto del catálogo.'
          );
        end if;
        v_item := (v_item - 'catalog_operation_id') || jsonb_build_object(
          'id_identificacion', v_current ->> 'id_identificacion'
        );
      end if;
      v_resolved := v_resolved || jsonb_build_array(v_item);
    end loop;
    v_data := v_resolved;
    if exists (
      select 1
      from jsonb_array_elements(v_data) as requested
      join public.repuestos as existing
        on existing.id = (requested ->> 'id')::uuid
      where not public.offline_json_fields_match(
        to_jsonb(existing),
        jsonb_build_object(
          'id', requested -> 'id',
          'formato_folio', requested -> 'formato_folio',
          'id_repuesto', requested -> 'id_repuesto',
          'id_identificacion', requested -> 'id_identificacion',
          'traido_por', requested -> 'traido_por',
          'cantidad', requested -> 'cantidad',
          'descripcion', requested -> 'descripcion',
          'precio_neto_unitario', requested -> 'precio_neto_unitario',
          'costo_unitario', requested -> 'costo_unitario'
        )
      )
    ) then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'Un repuesto con el mismo identificador contiene otros datos.'
      );
    end if;

    if v_kind = 'repuesto.create'
       and nullif(p_payload ->> 'catalog_description', '') is not null then
      v_result := public.save_repuesto_with_catalog_profit_atomic(
        v_data -> 0,
        p_payload ->> 'catalog_description'
      );
    else
      v_result := public.save_repuestos_profit_atomic(v_data);
    end if;

  elsif v_kind = 'repuesto.update' then
    v_id := nullif(p_payload ->> 'id', '')::uuid;
    v_data := coalesce(p_payload -> 'data', '{}'::jsonb);
    v_base := coalesce(p_payload -> 'base', '{}'::jsonb);
    select to_jsonb(repuesto) into v_current
    from public.repuestos as repuesto
    where repuesto.id = v_id and repuesto.deleted_at is null
    for update;

    if v_current is null then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'El repuesto ya no existe o fue eliminado.'
      );
    elsif public.offline_json_fields_match(v_current, v_data) then
      v_result := v_current;
    elsif jsonb_object_length(v_base) > 0
          and not public.offline_json_fields_match(v_current, v_base) then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'Otra persona cambió este repuesto mientras estabas offline.',
        'server', v_current,
        'local', v_data
      );
    else
      v_result := case
        when nullif(p_payload ->> 'catalog_description', '') is null
          then public.update_repuesto_profit_atomic(v_id, v_data)
        else public.update_repuesto_with_catalog_profit_atomic(
          v_id, v_data, p_payload ->> 'catalog_description'
        )
      end;
    end if;

  elsif v_kind = 'repuesto.delete' then
    v_id := nullif(p_payload ->> 'id', '')::uuid;
    select to_jsonb(repuesto) into v_current
    from public.repuestos as repuesto where repuesto.id = v_id for update;
    if v_current is null then
      v_result := jsonb_build_object('id', v_id, 'deleted', true);
    elsif v_current -> 'deleted_at' <> 'null'::jsonb then
      v_result := v_current;
    elsif jsonb_object_length(coalesce(p_payload -> 'base', '{}'::jsonb)) > 0
          and not public.offline_json_fields_match(
            v_current, p_payload -> 'base'
          ) then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'El repuesto cambió antes de poder eliminarlo.',
        'server', v_current
      );
    else
      update public.repuestos as repuesto
      set deleted_at = now(), deleted_by = v_user_id
      where id = v_id and deleted_at is null
      returning to_jsonb(repuesto) into v_result;
    end if;

  elsif v_kind in ('repuesto.restore', 'repuesto.deletion_request') then
    v_id := nullif(p_payload ->> 'id', '')::uuid;
    select to_jsonb(repuesto) into v_current
    from public.repuestos as repuesto where repuesto.id = v_id for update;
    if v_current is null then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'El repuesto ya no existe.'
      );
    elsif v_kind = 'repuesto.restore' then
      update public.repuestos as repuesto
      set deleted_at = null, deleted_by = null, deletion_requested = false
      where repuesto.id = v_id
      returning to_jsonb(repuesto) into v_result;
    elsif coalesce((v_current ->> 'deletion_requested')::boolean, false)
          = coalesce((p_payload ->> 'requested')::boolean, false) then
      v_result := v_current;
    else
      update public.repuestos as repuesto
      set deletion_requested = coalesce(
        (p_payload ->> 'requested')::boolean, false
      )
      where repuesto.id = v_id
      returning to_jsonb(repuesto) into v_result;
    end if;

  elsif v_kind = 'servicio.create' then
    v_data := p_payload;
    v_format_operation_id := nullif(
      p_payload ->> 'format_operation_id', ''
    )::uuid;
    if v_format_operation_id is not null then
      select receipt.result into v_resolved
      from public.offline_mutation_receipts as receipt
      where receipt.operation_id = v_format_operation_id
        and receipt.user_id = v_user_id
        and receipt.mutation_kind = 'format.create';
      if v_resolved is null then
        return jsonb_build_object(
          'status', 'deferred',
          'message', 'Primero debe sincronizarse la creación del formato.'
        );
      end if;
      v_data := (v_data - 'format_operation_id') || jsonb_build_object(
        'formato_folio', v_resolved ->> 'folio'
      );
    end if;
    v_id := nullif(v_data ->> 'id', '')::uuid;
    v_folio := trim(coalesce(v_data ->> 'formato_folio', ''));
    v_name := regexp_replace(trim(coalesce(v_data ->> 'servicio', '')), '\s+', ' ', 'g');
    if v_id is null or v_folio = '' or public.normalize_service_name(v_name) = '' then
      raise exception 'El servicio pendiente no es válido' using errcode = '22023';
    end if;

    insert into public.servicios as servicio(
      id, formato_folio, servicio, precio_mano_obra, created_at
    ) values (
      v_id, v_folio, v_name,
      nullif(nullif(v_data ->> 'precio_mano_obra', '')::numeric, 0),
      coalesce(nullif(v_data ->> 'created_at', '')::timestamptz, now())
    )
    on conflict (
      formato_folio, public.normalize_service_name(servicio)
    ) where deleted_at is null
    do nothing
    returning to_jsonb(servicio.*) into v_result;

    if v_result is null then
      select to_jsonb(servicio.*) into v_result
      from public.servicios as servicio
      where servicio.formato_folio = v_folio
        and public.normalize_service_name(servicio.servicio) =
            public.normalize_service_name(v_name)
        and servicio.deleted_at is null
      order by servicio.created_at, servicio.id
      limit 1;
    end if;

  elsif v_kind = 'servicio.price' then
    v_id := nullif(p_payload ->> 'id', '')::uuid;
    v_folio := nullif(trim(p_payload ->> 'formato_folio'), '');
    v_format_operation_id := nullif(
      p_payload ->> 'format_operation_id', ''
    )::uuid;
    if v_format_operation_id is not null then
      select receipt.result into v_resolved
      from public.offline_mutation_receipts as receipt
      where receipt.operation_id = v_format_operation_id
        and receipt.user_id = v_user_id
        and receipt.mutation_kind = 'format.create';
      if v_resolved is null then
        return jsonb_build_object(
          'status', 'deferred',
          'message', 'Primero debe sincronizarse la creación del formato.'
        );
      end if;
      v_folio := nullif(trim(v_resolved ->> 'folio'), '');
    end if;
    v_name := nullif(trim(p_payload ->> 'servicio'), '');
    select to_jsonb(servicio.*) into v_current
    from public.servicios as servicio
    where servicio.deleted_at is null
      and (
        servicio.id = v_id
        or (
          v_folio is not null and v_name is not null
          and servicio.formato_folio = v_folio
          and public.normalize_service_name(servicio.servicio) =
              public.normalize_service_name(v_name)
        )
      )
    order by (servicio.id = v_id) desc
    limit 1
    for update;
    if v_current is null then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'El servicio ya no existe o fue eliminado.'
      );
    end if;
    v_id := (v_current ->> 'id')::uuid;
    if v_current -> 'precio_mano_obra' = p_payload -> 'precio_mano_obra' then
      v_result := v_current;
    elsif p_payload ? 'base_precio'
          and v_current -> 'precio_mano_obra' <> p_payload -> 'base_precio' then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'Otra persona cambió el precio de este servicio.',
        'server', v_current,
        'local', p_payload -> 'precio_mano_obra'
      );
    else
      v_result := public.set_servicio_precio(
        v_id, nullif(p_payload ->> 'precio_mano_obra', '')::numeric
      );
    end if;

  elsif v_kind = 'servicio.delete' then
    v_id := nullif(p_payload ->> 'id', '')::uuid;
    v_base := coalesce(p_payload -> 'base', '{}'::jsonb);
    v_folio := nullif(trim(v_base ->> 'formato_folio'), '');
    v_format_operation_id := nullif(
      p_payload ->> 'format_operation_id', ''
    )::uuid;
    if v_format_operation_id is not null then
      select receipt.result into v_resolved
      from public.offline_mutation_receipts as receipt
      where receipt.operation_id = v_format_operation_id
        and receipt.user_id = v_user_id
        and receipt.mutation_kind = 'format.create';
      if v_resolved is null then
        return jsonb_build_object(
          'status', 'deferred',
          'message', 'Primero debe sincronizarse la creación del formato.'
        );
      end if;
      v_folio := nullif(trim(v_resolved ->> 'folio'), '');
    end if;
    v_name := nullif(trim(v_base ->> 'servicio'), '');
    select to_jsonb(servicio.*) into v_current
    from public.servicios as servicio
    where servicio.id = v_id
      or (
        v_folio is not null and v_name is not null
        and servicio.formato_folio = v_folio
        and public.normalize_service_name(servicio.servicio) =
            public.normalize_service_name(v_name)
      )
    order by (servicio.id = v_id) desc
    limit 1
    for update;
    if v_current is null then
      v_result := jsonb_build_object('id', v_id, 'deleted', true);
    elsif v_current -> 'deleted_at' <> 'null'::jsonb then
      v_result := v_current;
    elsif jsonb_object_length(v_base) > 0
          and not public.offline_json_fields_match(v_current, v_base) then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'El servicio cambió antes de poder eliminarlo.',
        'server', v_current
      );
    else
      v_id := (v_current ->> 'id')::uuid;
      update public.servicios as servicio
      set deleted_at = now(), deleted_by = v_user_id
      where id = v_id and deleted_at is null
      returning to_jsonb(servicio.*) into v_result;
    end if;

  elsif v_kind in ('servicio.restore', 'servicio.deletion_request') then
    v_id := nullif(p_payload ->> 'id', '')::uuid;
    select to_jsonb(servicio.*) into v_current
    from public.servicios as servicio where servicio.id = v_id for update;
    if v_current is null then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'El servicio ya no existe.'
      );
    elsif v_kind = 'servicio.restore' then
      update public.servicios as servicio
      set deleted_at = null, deleted_by = null, deletion_requested = false
      where servicio.id = v_id
      returning to_jsonb(servicio.*) into v_result;
    elsif coalesce((v_current ->> 'deletion_requested')::boolean, false)
          = coalesce((p_payload ->> 'requested')::boolean, false) then
      v_result := v_current;
    else
      update public.servicios as servicio
      set deletion_requested = coalesce(
        (p_payload ->> 'requested')::boolean, false
      )
      where servicio.id = v_id
      returning to_jsonb(servicio.*) into v_result;
    end if;

  elsif v_kind = 'profile.update' then
    v_data := coalesce(p_payload -> 'data', '{}'::jsonb);
    v_base := coalesce(p_payload -> 'base', '{}'::jsonb);
    select to_jsonb(profile) into v_current
    from public.profiles as profile
    where profile.id = v_user_id
    for update;
    if v_current is null then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'El perfil del usuario ya no existe.'
      );
    elsif public.offline_json_fields_match(v_current, v_data) then
      v_result := v_current;
    elsif jsonb_object_length(v_base) > 0
          and not public.offline_json_fields_match(v_current, v_base) then
      return jsonb_build_object(
        'status', 'conflict',
        'message', 'El perfil cambió en otro dispositivo.',
        'server', v_current,
        'local', v_data
      );
    else
      update public.profiles as profile
      set full_name = nullif(trim(v_data ->> 'full_name'), ''),
          username = nullif(trim(v_data ->> 'username'), '')
      where profile.id = v_user_id
      returning to_jsonb(profile) into v_result;
    end if;

  elsif v_kind = 'setting.set' then
    v_name := nullif(trim(p_payload ->> 'key'), '');
    if v_name is null or not (p_payload ? 'value') then
      raise exception 'El ajuste pendiente no es válido' using errcode = '22023';
    end if;
    insert into public.app_settings as setting(key, value)
    values (v_name, (p_payload ->> 'value')::boolean)
    on conflict (key) do update set value = excluded.value
    returning to_jsonb(setting) into v_result;

  elsif v_kind in ('weekly_goal.set', 'weekly_goal.clear') then
    if v_kind = 'weekly_goal.set' then
      perform public.set_weekly_labor_goal(
        (p_payload ->> 'start_date')::date,
        (p_payload ->> 'end_date')::date,
        (p_payload ->> 'goal')::numeric
      );
      v_result := jsonb_build_object(
        'start_date', p_payload ->> 'start_date',
        'end_date', p_payload ->> 'end_date',
        'goal', p_payload -> 'goal'
      );
    else
      perform public.clear_weekly_labor_goal(
        (p_payload ->> 'start_date')::date,
        (p_payload ->> 'end_date')::date
      );
      v_result := jsonb_build_object(
        'start_date', p_payload ->> 'start_date',
        'end_date', p_payload ->> 'end_date',
        'cleared', true
      );
    end if;

  elsif v_kind = 'invoice.status' then
    raise exception 'El cambio manual de estado de facturas fue eliminado'
      using errcode = '22023';

  elsif v_kind = 'invoice.upsert' then
    raise exception 'Las facturas se crean desde el flujo de formatos'
      using errcode = '22023';

  elsif v_kind = 'invoice.payment_create' then
    v_result := public.registrar_abono_v2(
      (p_payload ->> 'monto')::numeric,
      (p_payload ->> 'fecha')::date,
      p_payload ->> 'id_formato',
      p_payload ->> 'origen'
    );

  elsif v_kind = 'invoice.payment_delete' then
    v_result := public.eliminar_abono_v2(
      (p_payload ->> 'id')::bigint
    );

  elsif v_kind = 'invoice.delete' then
    perform public.eliminar_factura_y_abonos_asociados(
      p_payload ->> 'id_formato'
    );
    v_result := jsonb_build_object(
      'id_formato', p_payload ->> 'id_formato', 'deleted', true
    );

  elsif v_kind = 'settlement.create' then
    v_result := public.close_weekly_settlement_with_parts(
      (p_payload ->> 'start_date')::date,
      (p_payload ->> 'end_date')::date,
      (p_payload ->> 'wage_fund_percentage')::numeric,
      coalesce(p_payload -> 'items', '[]'::jsonb),
      coalesce(p_payload -> 'workers', '[]'::jsonb),
      coalesce((p_payload ->> 'total_bonus')::numeric, 0),
      coalesce(p_payload -> 'deferrals', '[]'::jsonb)
    );

  elsif v_kind in ('settlement.delete', 'settlement.restore') then
    if v_kind = 'settlement.delete' then
      v_result := public.delete_weekly_settlement(
        (p_payload ->> 'id')::uuid, false
      );
    else
      v_result := public.restore_weekly_settlement(
        (p_payload ->> 'id')::uuid
      );
    end if;

  elsif v_kind = 'catalog.create' then
    v_result := to_jsonb(public.create_catalogo_repuesto_atomic(
      p_payload ->> 'descripcion'
    ));

  elsif v_kind in ('vehicle.brand_upsert', 'vehicle.type_upsert') then
    v_name := regexp_replace(trim(p_payload ->> 'name'), '\s+', ' ', 'g');
    perform pg_advisory_xact_lock(
      hashtextextended(v_kind || ':' || lower(v_name), 0)
    );
    if v_kind = 'vehicle.brand_upsert' then
      select to_jsonb(marca) into v_result
      from public.marcas as marca
      where lower(trim(marca.nombre)) = lower(v_name)
      limit 1;
      if v_result is null then
        insert into public.marcas as marca(nombre) values (v_name)
        returning to_jsonb(marca) into v_result;
      end if;
    else
      select to_jsonb(tipo) into v_result
      from public.tipos_vehiculo as tipo
      where lower(trim(tipo.nombre_tipo)) = lower(v_name)
        and lower(trim(tipo.marca_nombre)) = lower(trim(p_payload ->> 'brand'))
      limit 1;
      if v_result is null then
        insert into public.tipos_vehiculo as tipo(nombre_tipo, marca_nombre)
        values (v_name, trim(p_payload ->> 'brand'))
        returning to_jsonb(tipo) into v_result;
      end if;
    end if;

  elsif v_kind = 'vehicle.upsert' then
    v_name := upper(trim(p_payload ->> 'plate'));
    perform pg_advisory_xact_lock(hashtextextended('vehicle:' || v_name, 0));
    select to_jsonb(vehicle) into v_result
    from public.vehiculos_registrados as vehicle
    where upper(trim(vehicle.placa)) = v_name
    limit 1;
    if v_result is null then
      insert into public.vehiculos_registrados as vehicle(
        placa, marca, tipo_vehiculo
      ) values (
        v_name, trim(p_payload ->> 'brand'), trim(p_payload ->> 'type')
      ) returning to_jsonb(vehicle) into v_result;
    end if;

  elsif v_kind in ('customer.upsert', 'customer.update', 'customer.deactivate') then
    v_data := coalesce(p_payload -> 'data', '{}'::jsonb);
    if v_kind = 'customer.upsert' then
      insert into public.clientes_fiscales as customer
      (
        tipo_documento, numero_documento, dv, razon_social, nombre_comercial,
        direccion, codigo_ciudad, ciudad, departamento, codigo_depto,
        codigo_postal, pais, telefono, email, tipo_persona, regimen_fiscal,
        responsabilidad, activo
      )
      select
        proposed.tipo_documento, proposed.numero_documento, proposed.dv,
        proposed.razon_social, proposed.nombre_comercial, proposed.direccion,
        proposed.codigo_ciudad, proposed.ciudad, proposed.departamento,
        proposed.codigo_depto, proposed.codigo_postal, proposed.pais,
        proposed.telefono, proposed.email, proposed.tipo_persona,
        proposed.regimen_fiscal, proposed.responsabilidad, proposed.activo
      from jsonb_populate_record(
        null::public.clientes_fiscales, v_data
      ) as proposed
      on conflict (numero_documento) do update set
        tipo_documento = excluded.tipo_documento,
        dv = excluded.dv,
        razon_social = excluded.razon_social,
        nombre_comercial = excluded.nombre_comercial,
        direccion = excluded.direccion,
        codigo_ciudad = excluded.codigo_ciudad,
        ciudad = excluded.ciudad,
        departamento = excluded.departamento,
        codigo_depto = excluded.codigo_depto,
        codigo_postal = excluded.codigo_postal,
        pais = excluded.pais,
        telefono = excluded.telefono,
        email = excluded.email,
        tipo_persona = excluded.tipo_persona,
        regimen_fiscal = excluded.regimen_fiscal,
        responsabilidad = excluded.responsabilidad,
        activo = excluded.activo
      returning to_jsonb(customer) into v_result;
    elsif v_kind = 'customer.update' then
      update public.clientes_fiscales as customer
      set (tipo_documento, numero_documento, dv, razon_social, nombre_comercial,
           direccion, codigo_ciudad, ciudad, departamento, codigo_depto,
           codigo_postal, pais, telefono, email, tipo_persona, regimen_fiscal,
           responsabilidad, activo) =
          (proposed.tipo_documento, proposed.numero_documento, proposed.dv,
           proposed.razon_social, proposed.nombre_comercial,
           proposed.direccion, proposed.codigo_ciudad, proposed.ciudad,
           proposed.departamento, proposed.codigo_depto,
           proposed.codigo_postal, proposed.pais, proposed.telefono,
           proposed.email, proposed.tipo_persona, proposed.regimen_fiscal,
           proposed.responsabilidad, proposed.activo)
      from jsonb_populate_record(
        null::public.clientes_fiscales, v_data
      ) as proposed
      where customer.id = (p_payload ->> 'id')::integer
      returning to_jsonb(customer) into v_result;
    else
      update public.clientes_fiscales as customer
      set activo = false
      where customer.id = (p_payload ->> 'id')::integer
      returning to_jsonb(customer) into v_result;
    end if;

  elsif v_kind = 'supplier_invoice.create' then
    v_data := coalesce(p_payload -> 'data', '{}'::jsonb);
    insert into public.facturas_proveedores as invoice(
      id_formato, proveedor, monto, fecha, url_imagen, created_at
    ) values (
      v_data ->> 'id_formato', v_data ->> 'proveedor',
      (v_data ->> 'monto')::numeric, (v_data ->> 'fecha')::timestamptz,
      v_data ->> 'url_imagen',
      coalesce((v_data ->> 'created_at')::timestamptz, now())
    ) returning to_jsonb(invoice) into v_result;

  elsif v_kind in ('time.start', 'time.finish') then
    v_folio := nullif(trim(p_payload ->> 'formato_folio'), '');
    v_format_operation_id := nullif(
      p_payload ->> 'format_operation_id', ''
    )::uuid;
    if v_format_operation_id is not null then
      select receipt.result into v_resolved
      from public.offline_mutation_receipts as receipt
      where receipt.operation_id = v_format_operation_id
        and receipt.user_id = v_user_id
        and receipt.mutation_kind = 'format.create';
      if v_resolved is null then
        return jsonb_build_object(
          'status', 'deferred',
          'message', 'Primero debe sincronizarse la creación del formato.'
        );
      end if;
      v_folio := v_resolved ->> 'folio';
    end if;
    if v_kind = 'time.start' then
      insert into public.registro_tiempos as timing(
        formato_folio, servicio_asociado, hora_inicio
      ) values (
        v_folio, p_payload ->> 'servicio',
        (p_payload ->> 'started_at')::timestamptz
      ) returning to_jsonb(timing) into v_result;
    else
      update public.registro_tiempos
      set hora_fin = (p_payload ->> 'finished_at')::timestamptz
      where formato_folio = v_folio and hora_fin is null;
      v_result := jsonb_build_object(
        'formato_folio', v_folio,
        'finished_at', p_payload ->> 'finished_at'
      );
    end if;

  elsif v_kind = 'invoice.detach' then
    v_result := public.desvincular_factura_pdf_v2(
      p_payload ->> 'id_formato'
    );
  else
    raise exception 'Tipo de operación offline no permitido: %', v_kind
      using errcode = '22023';
  end if;

  insert into public.offline_mutation_receipts(
    operation_id, user_id, mutation_kind, entity_key, payload_hash, result
  ) values (
    p_operation_id, v_user_id, v_kind, p_entity_key, v_payload_hash,
    coalesce(v_result, '{}'::jsonb)
  );

  return jsonb_build_object(
    'status', 'applied',
    'operation_id', p_operation_id,
    'result', coalesce(v_result, '{}'::jsonb)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cleanup_old_time_tracking()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Eliminar registros de notificaciones inactivas más antiguos de 30 días
    DELETE FROM notification_time_tracking
    WHERE notification_id IN (
        SELECT id FROM update_notifications
        WHERE is_active = false
        AND updated_at < NOW() - INTERVAL '30 days'
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_next_clave_control_number()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    max_num INT;
BEGIN
    -- Busca el número más alto en la columna clave_key que sigue el patrón 'F-'
    -- COALESCE se asegura de que si la tabla está vacía, empecemos en 0.
    SELECT COALESCE(MAX(CAST(SUBSTRING(clave_control FROM 'F-(\d+)') AS INTEGER)), 0)
    INTO max_num
    FROM public.formatos
    WHERE clave_key ~ '^F-\d+$';

    -- Devuelve el siguiente número
    RETURN max_num + 1;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.jsonb_object_length(p_value jsonb)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select count(*)::integer
  from jsonb_object_keys(
    case
      when jsonb_typeof(coalesce(p_value, '{}'::jsonb)) = 'object'
        then coalesce(p_value, '{}'::jsonb)
      else '{}'::jsonb
    end
  );
$function$
;

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_reporte_variacion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (
    new.estado = 'LISTO'
    and old.estado is distinct from 'LISTO'
  ) or (
    new.estado = 'FINALIZADO'
    and old.estado = 'ACTIVO'
  ) then
    delete from public.reportes_variacion where id_formato = new.id;
    insert into public.reportes_variacion(fecha, mano_obra, total, id_formato)
    values (
      coalesce(new.fecha_salida, new.fecha_entrada, current_date),
      coalesce(new.labor_confirmed_amount, new.costo_mano_obra, 0),
      coalesce(new.labor_confirmed_amount, new.costo_mano_obra, 0)
        + coalesce(new.costo_repuestos, 0),
      new.id
    );
  elsif new.estado = 'ACTIVO' and old.estado in ('LISTO', 'FINALIZADO') then
    delete from public.reportes_variacion where id_formato = new.id;
  end if;
  return new;
exception when others then
  raise warning 'Error al registrar variación del formato %: %', new.folio, sqlerrm;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.actualizar_costos_formato()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    formato_folio_afectado TEXT;
    nuevo_costo_repuestos NUMERIC;
    mano_obra_actual NUMERIC;
BEGIN
    IF (TG_OP = 'DELETE') THEN
        formato_folio_afectado := OLD.id_repuesto;
    ELSE
        formato_folio_afectado := NEW.id_repuesto;
    END IF;

    IF formato_folio_afectado IS NULL THEN
        IF (TG_OP = 'DELETE') THEN RETURN OLD; ELSE RETURN NEW; END IF;
    END IF;

    SELECT COALESCE(SUM(costo_total_linea), 0) INTO nuevo_costo_repuestos FROM repuestos WHERE id_repuesto = formato_folio_afectado;
    SELECT COALESCE(costo_mano_obra, 0) INTO mano_obra_actual FROM formatos WHERE folio = formato_folio_afectado;

    UPDATE formatos SET costo_repuestos = nuevo_costo_repuestos, costo_total = mano_obra_actual + nuevo_costo_repuestos WHERE folio = formato_folio_afectado;

    IF (TG_OP = 'DELETE') THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_global_test_environment_enabled(p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_environment_id uuid;
begin
  if v_user_id is null then
    raise exception 'Usuario no autenticado' using errcode = '42501';
  end if;
  if not public.is_current_user_admin() then
    raise exception 'Solo un administrador puede usar el entorno global de pruebas'
      using errcode = '42501';
  end if;

  if p_enabled then
    insert into public.global_test_environments(
      owner_id,
      scope_key,
      last_activated_at
    ) values (
      v_user_id,
      'shared',
      now()
    )
    on conflict (scope_key) do update
      set last_activated_at = excluded.last_activated_at
    returning id into v_environment_id;
  else
    select mode.environment_id
    into v_environment_id
    from public.format_development_modes mode
    where mode.user_id = v_user_id;
  end if;

  insert into public.format_development_modes(
    user_id,
    is_enabled,
    environment_id,
    updated_at
  ) values (
    v_user_id,
    p_enabled,
    v_environment_id,
    now()
  )
  on conflict (user_id) do update set
    is_enabled = excluded.is_enabled,
    environment_id = coalesce(
      excluded.environment_id,
      public.format_development_modes.environment_id
    ),
    updated_at = excluded.updated_at;

  return jsonb_build_object(
    'is_enabled', p_enabled,
    'environment_id', v_environment_id,
    'is_shared', true
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.exit_global_test_environment(p_delete_data boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_environment_id uuid;
  v_table text;
  v_count bigint;
  v_total bigint := 0;
  v_affected_admins bigint := 0;
  v_counts jsonb := '{}'::jsonb;
begin
  if v_user_id is null then
    raise exception 'Usuario no autenticado' using errcode = '42501';
  end if;
  if not public.is_current_user_admin() then
    raise exception 'Solo un administrador puede salir del entorno global de pruebas'
      using errcode = '42501';
  end if;

  select mode.environment_id
  into v_environment_id
  from public.format_development_modes mode
  where mode.user_id = v_user_id
  for update;

  if p_delete_data and v_environment_id is not null then
    select count(*)
    into v_affected_admins
    from public.format_development_modes mode
    where mode.environment_id = v_environment_id
      and mode.is_enabled;

    foreach v_table in array array[
      'abonos', 'catalogo_repuestos', 'clientes_fiscales', 'deletion_requests',
      'facturas', 'facturas_electronicas', 'facturas_proveedores',
      'format_state_transitions', 'formatos', 'formatos_globales', 'marcas',
      'offline_mutation_receipts', 'registro_tiempos', 'reportes_variacion',
      'repuestos', 'servicios', 'settlement_deferrals',
      'settlement_deferrals_voided', 'settlement_items',
      'settlement_items_voided', 'settlement_part_profit_snapshots',
      'settlement_worker_payments', 'tipos_vehiculo', 'trashed_photos',
      'vehiculos_registrados', 'weekly_settlements'
    ] loop
      if to_regclass(format('public.%I', v_table)) is null then
        continue;
      end if;
      execute format(
        'select count(*) from public.%I where test_environment_id = $1',
        v_table
      ) into v_count using v_environment_id;
      if v_count > 0 then
        v_counts := v_counts || jsonb_build_object(v_table, v_count);
        v_total := v_total + v_count;
      end if;
    end loop;

    perform set_config(
      'app.global_test_cleanup_id',
      v_environment_id::text,
      true
    );

    delete from public.global_test_environments environment
    where environment.id = v_environment_id
      and environment.scope_key = 'shared';

    -- Deleting the shared dataset exits every administrator so no session can
    -- silently fall through to production with a stale test banner.
    update public.format_development_modes mode
    set is_enabled = false,
        environment_id = null,
        previous_environment_ids = array[]::uuid[],
        updated_at = now()
    where mode.environment_id is null
       or mode.environment_id = v_environment_id;
  else
    update public.format_development_modes mode
    set is_enabled = false,
        updated_at = now()
    where mode.user_id = v_user_id;
  end if;

  return jsonb_build_object(
    'data_deleted', p_delete_data,
    'deleted_records', v_total,
    'deleted_by_table', v_counts,
    'affected_admins', v_affected_admins,
    'environment_id', case
      when p_delete_data then null
      else v_environment_id
    end
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_formatos_costs_from_repuestos()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  new_costo_repuestos NUMERIC;
  current_costo_mano_obra NUMERIC;
  target_folio TEXT;
BEGIN
  -- Identifica a qué formato (por su folio) pertenece el repuesto que cambió
  IF (TG_OP = 'DELETE') THEN
    target_folio := OLD.formato_folio; -- CORREGIDO: Usa 'formato_folio' de tu tabla
  ELSE
    target_folio := NEW.formato_folio; -- CORREGIDO: Usa 'formato_folio' de tu tabla
  END IF;

  -- Suma el total de todos los repuestos para ese formato
  -- CORREGIDO: Usa las columnas `cantidad` y `costo_unitario` de tu tabla.
  SELECT COALESCE(SUM(cantidad * costo_unitario), 0)
  INTO new_costo_repuestos
  FROM repuestos
  WHERE formato_folio = target_folio;

  -- Obtiene el costo actual de la mano de obra de ese formato
  SELECT COALESCE(costo_mano_obra, 0)
  INTO current_costo_mano_obra
  FROM formatos
  WHERE folio = target_folio; -- La tabla formatos se conecta con 'folio'

  -- Finalmente, actualiza la tabla de formatos con los nuevos totales
  UPDATE formatos
  SET
    costo_repuestos = new_costo_repuestos,
    costo_total = current_costo_mano_obra + new_costo_repuestos
  WHERE folio = target_folio;

  RETURN NULL; -- Requerido por la sintaxis del trigger
END;
$function$
;

