CREATE OR REPLACE FUNCTION public.normalize_service_name(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select regexp_replace(
    translate(
      lower(trim(coalesce(p_value, ''))),
      U&'\00E0\00E1\00E2\00E3\00E4\00E5\00E8\00E9\00EA\00EB\00EC\00ED\00EE\00EF\00F2\00F3\00F4\00F5\00F6\00F9\00FA\00FB\00FC\00FD\00FF\00F1',
      'aaaaaaeeeeiiiioooooouuuuyyn'
    ),
    '\s+',
    ' ',
    'g'
  );
$function$
;

CREATE OR REPLACE FUNCTION public.permanently_delete_repuesto(p_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE profiles.id = auth.uid()
    AND LOWER(profiles.role) = 'admin'
  ) THEN
    RAISE EXCEPTION 'not_allowed';
  END IF;

  DELETE FROM repuestos WHERE id::text = p_id;
END;
$function$
;

