CREATE OR REPLACE FUNCTION public.sync_formato_to_global()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- DEBUG: Escribe un mensaje en los logs para confirmar que el trigger se activó.
  RAISE NOTICE '[DEBUG] Trigger de sincronización activado para el folio: %', NEW.folio;

  -- Lógica de actualización (sin cambios)
  UPDATE public.formatos_globales
  SET
    fecha = NEW.fecha_entrada,
    placa = NEW.placa,
    marca = NEW.marca,
    tipo = NEW.tipo_vehiculo,
    modelo = NEW.modelo,
    cliente = NEW.nombre_cliente,
    conductor = NEW.nombre_conductor,
    telefono = NEW.telefono_contacto,
    kilometraje = NEW.kilometraje,
    trabajos_realizados = NEW.trabajos_realizados,
    clave_control = NEW.clave_control,
    observaciones = NEW.observaciones,
    mano_obra = NEW.costo_mano_obra,
    precio_repuestos = NEW.costo_repuestos,
    total = NEW.costo_total
  WHERE id = NEW.folio;

  -- DEBUG: Verifica si la actualización encontró una fila y escribe el resultado.
  IF FOUND THEN
    RAISE NOTICE '[DEBUG] ÉXITO: Se encontró y actualizó la fila en formatos_globales para el id: %', NEW.folio;
  ELSE
    RAISE NOTICE '[DEBUG] ADVERTENCIA: No se encontró una fila correspondiente en formatos_globales para el id: %', NEW.folio;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_and_sync_all_formats()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  target_folio_text TEXT;
  new_costo_repuestos NUMERIC;
  current_costo_mano_obra NUMERIC;
  new_costo_total NUMERIC;
BEGIN
  -- 1. Identifica el folio del formato afectado.
  IF (TG_OP = 'DELETE') THEN
    target_folio_text := OLD.formato_folio;
  ELSE
    target_folio_text := NEW.formato_folio;
  END IF;

  -- 2. Recalcula los costos.
  SELECT COALESCE(SUM(cantidad * costo_unitario), 0)
  INTO new_costo_repuestos
  FROM public.repuestos
  WHERE formato_folio = target_folio_text;

  SELECT COALESCE(costo_mano_obra, 0)
  INTO current_costo_mano_obra
  FROM public.formatos
  WHERE folio = target_folio_text;

  new_costo_total := current_costo_mano_obra + new_costo_repuestos;

  -- 3. Actualiza la tabla 'formatos'.
  UPDATE public.formatos
  SET
    costo_repuestos = new_costo_repuestos,
    costo_total = new_costo_total
  WHERE folio = target_folio_text;

  -- 4. Actualiza la tabla 'formatos_globales' inmediatamente después.
  UPDATE public.formatos_globales
  SET
    precio_repuestos = new_costo_repuestos,
    total = new_costo_total
  WHERE id = target_folio_text; -- Recuerda: formatos_globales.id = formatos.folio

  RETURN NULL;
END;
$function$
;

