CREATE OR REPLACE FUNCTION public.sync_non_cost_data()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE public.formatos_globales
  SET
    fecha = NEW.fecha_entrada,
    placa = NEW.placa,
    marca = NEW.marca,
    tipo = NEW.tipo_vehiculo,
    modelo = NEW.modelo,
    cliente = NEW.nombre_cliente,
    conductor = NEW.nombre_conductor,
    telefono = NEW.telefono_contacto,
    kilometraje = NEW.kilometraje,
    trabajos_realizados = NEW.trabajos_realizados,
    clave_control = NEW.clave_control,
    observaciones = NEW.observaciones,
    mano_obra = NEW.costo_mano_obra,
    -- Los costos de repuestos y total son manejados por el otro trigger.
    total = NEW.costo_mano_obra + COALESCE(precio_repuestos, 0) -- Recalcula el total aquí también
  WHERE id = NEW.folio;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  base_username TEXT;
  final_username TEXT;
  counter INT := 0;
BEGIN
  -- 1. Genera un nombre de usuario base a partir del nombre completo (ej: 'Juan Perez' -> 'juan.perez')
  base_username := lower(regexp_replace(new.raw_user_meta_data->>'full_name', '\s+', '.', 'g'));
  final_username := base_username;

  -- 2. Comprueba si el nombre de usuario ya existe. Si es así, le añade un número.
  --    (ej: si 'juan.perez' existe, intentará con 'juan.perez1', y así sucesivamente)
  WHILE EXISTS(SELECT 1 FROM public.profiles WHERE username = final_username) LOOP
    counter := counter + 1;
    final_username := base_username || counter::text;
  END LOOP;

  -- 3. Inserta el nuevo perfil con el nombre, y el nombre de usuario único que hemos generado.
  INSERT INTO public.profiles (id, full_name, username)
  VALUES (new.id, new.raw_user_meta_data->>'full_name', final_username);

  RETURN new;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_email_by_username(p_username text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  user_email TEXT;
BEGIN
  SELECT u.email INTO user_email
  FROM auth.users AS u
  JOIN public.profiles AS p ON u.id = p.id
  WHERE p.username = p_username;

  RETURN user_email;
END;
$function$
;

CREATE OR REPLACE FUNCTION private.factura_v2_is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
  select
    current_setting('request.jwt.claim.role', true) = 'service_role'
    or exists (
      select 1
      from public.profiles p
      where p.id = auth.uid()
        and lower(coalesce(p.role, '')) = 'admin'
        and coalesce(p.is_active, true)
        and p.deleted_at is null
    );
$function$
;

CREATE OR REPLACE FUNCTION private.factura_v2_cutover_at()
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select cutover_at
  from public.factura_v2_config
  where id = true;
$function$
;

CREATE OR REPLACE FUNCTION private.factura_v2_is_legacy(p_created_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select p_created_at is null
    or p_created_at < private.factura_v2_cutover_at();
$function$
;

CREATE OR REPLACE FUNCTION private.factura_v2_state(p_total numeric, p_paid numeric)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  select case
    when coalesce(p_total, 0) <= 0 then 'BORRADOR'
    when coalesce(p_paid, 0) <= 0 then 'PENDIENTE'
    when coalesce(p_paid, 0) < coalesce(p_total, 0) then 'PARCIAL'
    else 'PAGADO'
  end;
$function$
;

CREATE OR REPLACE FUNCTION private.factura_v2_internal_write()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  select coalesce(current_setting('app.invoice_v2_internal', true), '') = 'true';
$function$
;

CREATE OR REPLACE FUNCTION private.sync_factura_v2_from_formato()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_invoice public.facturas%rowtype;
  v_total numeric := greatest(coalesce(new.costo_total, 0), 0);
  v_found boolean := false;
  v_changed_total boolean;
  v_changed_client boolean;
begin
  if new.deleted_at is not null or new.clave_key is null then
    return new;
  end if;

  select * into v_invoice
  from public.facturas
  where id_formato = new.clave_key
  for update;
  v_found := found;

  if not v_found then
    -- Un formato anterior al corte no estrena factura solo: la crea el flujo
    -- explicito de cotizacion cuando el usuario la genera.
    if private.factura_v2_is_legacy(new.created_at) then
      return new;
    end if;

    perform set_config('app.invoice_v2_internal', 'true', true);
    insert into public.facturas (
      id_formato,
      precio_factura,
      pagado,
      debe,
      factura_pdf,
      estado,
      cliente
    ) values (
      new.clave_key,
      v_total,
      0,
      v_total,
      null,
      private.factura_v2_state(v_total, 0),
      coalesce(new.nombre_cliente, '')
    );
    return new;
  end if;

  -- Una factura historica solo se congela cuando su cuenta ya esta cerrada:
  -- tiene dinero aplicado o el formato quedo liquidado. Congelarlas todas
  -- dejaba el total de un formato todavia abierto pegado al valor que tenia
  -- el dia del corte, asi que sumar repuestos no movia la factura.
  if private.factura_v2_is_legacy(v_invoice.created_at)
     and (
       coalesce(v_invoice.pagado, 0) > 0
       or new.estado = 'FINALIZADO'
       or exists (
         select 1
         from public.abonos as abono
         where abono.id_factura = v_invoice.id_formato
       )
     ) then
    return new;
  end if;

  if v_total < coalesce(v_invoice.pagado, 0) then
    raise exception 'El total del formato no puede ser menor que lo pagado en la factura';
  end if;

  v_changed_total := v_total is distinct from v_invoice.precio_factura;
  v_changed_client := coalesce(new.nombre_cliente, '')
    is distinct from coalesce(v_invoice.cliente, '');

  perform set_config('app.invoice_v2_internal', 'true', true);
  update public.facturas
  set precio_factura = v_total,
      debe = greatest(v_total - coalesce(v_invoice.pagado, 0), 0),
      estado = private.factura_v2_state(v_total, v_invoice.pagado),
      cliente = coalesce(new.nombre_cliente, ''),
      factura_pdf = case
        when v_changed_total or v_changed_client then null
        else v_invoice.factura_pdf
      end
  where id = v_invoice.id;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION private.guard_factura_v2_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
begin
  if tg_op = 'DELETE'
     and private.is_global_test_cleanup(old.test_environment_id) then
    return old;
  end if;

  if private.factura_v2_internal_write() then
    return coalesce(new, old);
  end if;

  if tg_op = 'INSERT' then
    raise exception 'La factura debe crearse desde el flujo de formatos';
  end if;

  if tg_op = 'DELETE' then
    if private.factura_v2_is_legacy(old.created_at) then
      raise exception 'LEGACY_READ_ONLY: la factura historica no se puede eliminar';
    end if;
    raise exception 'La factura debe eliminarse mediante el flujo administrativo';
  end if;

  if private.factura_v2_is_legacy(old.created_at) then
    raise exception 'LEGACY_READ_ONLY: la factura historica no se puede modificar';
  end if;

  raise exception 'La factura solo se modifica mediante el flujo de facturacion';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.obtener_factura_v2(p_factura_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_result jsonb;
begin
  if not private.factura_v2_is_admin() then
    raise exception 'Solo un administrador puede consultar facturas' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'factura', to_jsonb(f) || jsonb_build_object(
      'is_legacy', private.factura_v2_is_legacy(f.created_at),
      'is_read_only', private.factura_v2_is_legacy(f.created_at),
      'can_register_payment', coalesce(f.debe, 0) > 0
    ),
    'abonos', coalesce((
      select jsonb_agg(to_jsonb(a) order by a.fecha desc, a.id desc)
      from public.abonos a
      where a.id_factura = f.id_formato
    ), '[]'::jsonb)
  )
  into v_result
  from public.facturas f
  where f.id = p_factura_id;

  if v_result is null then
    raise exception 'La factura no existe' using errcode = 'P0002';
  end if;

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.eliminar_abono_v2(p_abono_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_abono public.abonos%rowtype;
  v_invoice public.facturas%rowtype;
  v_legacy boolean;
  v_new_paid numeric;
  v_new_debt numeric;
begin
  if not private.factura_v2_is_admin() then
    raise exception 'Solo un administrador puede eliminar abonos' using errcode = '42501';
  end if;

  select * into v_abono
  from public.abonos
  where id = p_abono_id
  for update;

  if not found then
    raise exception 'El abono no existe' using errcode = 'P0002';
  end if;
  if nullif(trim(v_abono.origen), '') is null then
    raise exception 'LEGACY_READ_ONLY: los abonos historicos no se pueden eliminar';
  end if;

  select * into v_invoice
  from public.facturas
  where id_formato = v_abono.id_factura
  for update;

  if not found then
    raise exception 'La factura asociada no existe' using errcode = 'P0002';
  end if;
  v_legacy := private.factura_v2_is_legacy(v_invoice.created_at);

  perform set_config('app.invoice_v2_internal', 'true', true);
  delete from public.abonos where id = v_abono.id;

  if v_legacy then
    v_new_paid := greatest(coalesce(v_invoice.pagado, 0) - v_abono.monto, 0);
    v_new_debt := coalesce(v_invoice.debe, 0) + v_abono.monto;
  else
    select coalesce(sum(a.monto), 0)
    into v_new_paid
    from public.abonos a
    where a.id_factura = v_invoice.id_formato;
    v_new_debt := greatest(coalesce(v_invoice.precio_factura, 0) - v_new_paid, 0);
  end if;

  update public.facturas
  set pagado = v_new_paid,
      debe = v_new_debt,
      estado = case
        when v_legacy then case when v_new_debt = 0 then 'PAGADO' else 'PENDIENTE' end
        else private.factura_v2_state(v_invoice.precio_factura, v_new_paid)
      end
  where id = v_invoice.id
  returning * into v_invoice;

  return jsonb_build_object('factura', to_jsonb(v_invoice), 'deleted_abono_id', p_abono_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.eliminar_factura_y_abonos_asociados(factura_id_formato_a_eliminar text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_invoice public.facturas%rowtype;
begin
  if not private.factura_v2_is_admin() then
    raise exception 'Solo un administrador puede eliminar facturas' using errcode = '42501';
  end if;

  select * into v_invoice
  from public.facturas
  where id_formato = factura_id_formato_a_eliminar
  for update;

  if not found then
    return;
  end if;
  if private.factura_v2_is_legacy(v_invoice.created_at) then
    raise exception 'LEGACY_READ_ONLY: la factura historica no se puede eliminar';
  end if;
  if exists (select 1 from public.abonos where id_factura = v_invoice.id_formato) then
    raise exception 'La factura con abonos no se puede eliminar';
  end if;

  perform set_config('app.invoice_v2_internal', 'true', true);
  delete from public.facturas where id = v_invoice.id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.eliminar_abono_y_actualizar_factura(abono_id_a_eliminar bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
begin
  perform public.eliminar_abono_v2(abono_id_a_eliminar);
end;
$function$
;

