 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select auth.uid() is not null
    and public.is_current_user_admin()
    and p_test_environment_id is not null
    and p_test_environment_id::text = nullif(
      pg_catalog.current_setting('app.global_test_cleanup_id', true),
      ''
    );
$function$
;

CREATE OR REPLACE FUNCTION public.tokens_servicio(p_value text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO ''
AS $function$
  SELECT coalesce(array_agg(DISTINCT t), '{}'::text[])
  FROM unnest(
         regexp_split_to_array(
           regexp_replace(public.normalize_service_name(p_value), '[^a-z0-9 ]', ' ', 'g'),
           '\s+')
       ) AS t
  WHERE length(t) >= 3
    AND t NOT IN (
      -- conectores
      'de','del','la','el','los','las','un','una','con','por','para','y','en',
      'al','su','sus','se','lo','este','esta','como',
      -- verbos y genéricos del taller: no identifican el trabajo
      'revision','revisar','cambio','cambiar','servicio','servicios',
      'mantenimiento','reparacion','reparar','ajuste','ajustar','arreglo',
      'arreglar','general','completo','completa','realizar','hacer',
      'vehiculo','carro','auto','mano','obra'
    )
$function$
;

CREATE OR REPLACE FUNCTION public.sugerencias_repuestos_formato(p_folio text, p_marca text DEFAULT NULL::text, p_tipo_vehiculo text DEFAULT NULL::text, p_limit integer DEFAULT 8)
 RETURNS TABLE(id uuid, id_identificacion text, descripcion text, created_at timestamp with time zone, usos bigint, puntaje numeric, servicio_origen text, costo_sugerido numeric, precio_fecha timestamp with time zone, precio_match text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  WITH mis AS MATERIALIZED (
    SELECT DISTINCT s.servicio, public.tokens_servicio(s.servicio) AS toks
    FROM public.servicios s
    WHERE s.formato_folio = p_folio
      AND s.deleted_at IS NULL
      AND cardinality(public.tokens_servicio(s.servicio)) > 0
  ),
  cand AS MATERIALIZED (
    SELECT s.formato_folio, s.servicio, public.tokens_servicio(s.servicio) AS toks
    FROM public.servicios s
    WHERE s.deleted_at IS NULL
      AND s.formato_folio <> p_folio
      AND cardinality(public.tokens_servicio(s.servicio)) > 0
  ),
  totales AS (
    SELECT formato_folio, count(DISTINCT servicio) AS n_serv
    FROM cand GROUP BY formato_folio
  ),
  coincidencias AS (
    SELECT c.formato_folio,
           c.servicio AS servicio_candidato,
           m.servicio AS servicio_origen,
           (SELECT count(*) FROM unnest(m.toks) t WHERE t = ANY(c.toks))::numeric
             / GREATEST(LEAST(cardinality(m.toks), cardinality(c.toks)), 1)::numeric AS sim
    FROM mis m
    JOIN cand c ON c.toks && m.toks
  ),
  buenas AS (
    SELECT * FROM coincidencias WHERE sim >= 0.6
  ),
  por_folio AS (
    SELECT b.formato_folio,
           max(b.sim) AS sim_max,
           sqrt(
             count(DISTINCT b.servicio_candidato)::numeric
             / GREATEST(t.n_serv, 1)::numeric
           ) AS cobertura,
           (array_agg(b.servicio_origen ORDER BY b.sim DESC))[1] AS servicio_origen
    FROM buenas b
    JOIN totales t ON t.formato_folio = b.formato_folio
    GROUP BY b.formato_folio, t.n_serv
  ),
  lineas AS (
    SELECT r.id_identificacion,
           b.servicio_origen,
           (b.sim_max * b.sim_max) * b.cobertura
             * CASE
                 WHEN p_marca IS NOT NULL AND f.marca IS NOT NULL
                      AND upper(btrim(f.marca)) = upper(btrim(p_marca))
                      AND p_tipo_vehiculo IS NOT NULL AND f.tipo_vehiculo IS NOT NULL
                      AND upper(btrim(f.tipo_vehiculo)) = upper(btrim(p_tipo_vehiculo))
                   THEN 3.0
                 WHEN p_marca IS NOT NULL AND f.marca IS NOT NULL
                      AND upper(btrim(f.marca)) = upper(btrim(p_marca))
                   THEN 1.6
                 ELSE 1.0
               END
             * (1.0 / (1.0 + (EXTRACT(EPOCH FROM (now() - r.created_at)) / 2629800.0 / 12.0)::numeric))
           AS score
    FROM por_folio b
    JOIN public.repuestos r ON r.id_repuesto = b.formato_folio
    LEFT JOIN public.formatos f ON f.folio = b.formato_folio
    WHERE r.deleted_at IS NULL
      AND r.id_identificacion IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.repuestos ya
        WHERE ya.id_repuesto = p_folio
          AND ya.deleted_at IS NULL
          AND ya.id_identificacion = r.id_identificacion
      )

    UNION ALL

    SELECT r.id_identificacion,
           NULL::text AS servicio_origen,
           CASE
             WHEN p_tipo_vehiculo IS NOT NULL AND f.tipo_vehiculo IS NOT NULL
                  AND upper(btrim(f.tipo_vehiculo)) = upper(btrim(p_tipo_vehiculo))
               THEN 3.0
             ELSE 1.0
           END
           * (1.0 / (1.0 + (EXTRACT(EPOCH FROM (now() - r.created_at)) / 2629800.0 / 12.0)::numeric))
           AS score
    FROM public.repuestos r
    JOIN public.formatos f ON f.folio = r.id_repuesto
    WHERE NOT EXISTS (SELECT 1 FROM mis)
      AND p_marca IS NOT NULL AND f.marca IS NOT NULL
      AND upper(btrim(f.marca)) = upper(btrim(p_marca))
      AND r.deleted_at IS NULL
      AND r.id_identificacion IS NOT NULL
      AND r.id_repuesto <> p_folio
      AND NOT EXISTS (
        SELECT 1 FROM public.repuestos ya
        WHERE ya.id_repuesto = p_folio
          AND ya.deleted_at IS NULL
          AND ya.id_identificacion = r.id_identificacion
      )
  ),
  agrupado AS (
    SELECT l.id_identificacion,
           count(*)::bigint AS usos,
           round(sum(l.score), 3) AS puntaje,
           mode() WITHIN GROUP (ORDER BY l.servicio_origen) AS servicio_origen
    FROM lineas l
    GROUP BY l.id_identificacion
  )
  SELECT c.id, c.id_identificacion, c.descripcion, c.created_at,
         a.usos, a.puntaje, a.servicio_origen,
         p.costo_sugerido, p.precio_fecha, p.precio_match
  FROM agrupado a
  JOIN public.catalogo_repuestos c
    ON c.id_identificacion = a.id_identificacion AND c.deleted_at IS NULL
  LEFT JOIN LATERAL public.precio_sugerido_repuesto(
    c.id_identificacion, p_marca, p_tipo_vehiculo
  ) p ON true
  ORDER BY a.puntaje DESC, a.usos DESC, c.descripcion
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 8), 1), 20)
$function$
;

CREATE OR REPLACE FUNCTION private.guard_abono_v2_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
begin
  if tg_op = 'DELETE'
     and private.is_global_test_cleanup(old.test_environment_id) then
    return old;
  end if;

  if tg_op = 'INSERT' then
    if nullif(trim(new.origen), '') is null then
      raise exception 'El origen del abono es obligatorio' using errcode = '22023';
    end if;
    if upper(trim(new.origen)) <> 'REGISTRADO_APP' then
      raise exception 'El origen del abono no es válido' using errcode = '22023';
    end if;
    if new.monto is null or new.monto <= 0 then
      raise exception 'El monto del abono debe ser mayor que cero' using errcode = '22023';
    end if;
    if new.fecha is null or new.fecha > current_date then
      raise exception 'La fecha del abono no puede ser futura' using errcode = '22023';
    end if;
    if not private.factura_v2_internal_write() then
      raise exception 'Los abonos solo se crean mediante el flujo administrativo'
        using errcode = '42501';
    end if;
    return new;
  end if;

  if private.factura_v2_internal_write() then
    return coalesce(new, old);
  end if;

  raise exception 'Los abonos solo se modifican mediante el flujo administrativo'
    using errcode = '42501';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.guard_settlement_restore()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.deleted_at is not null
     and new.deleted_at is null
     and coalesce(current_setting('app.settlement_action', true), '') <> 'restore' then
    raise exception
      'Usa Restaurar liquidación: sacarla de la papelera a mano deja sus formatos sin finalizar';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.send_format_back_to_workshop(p_format_id uuid, p_reason text, p_keep_exit_date boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_format public.formatos;
  v_previous_state text;
begin
  select * into v_format
  from public.formatos
  where id = p_format_id
  for update;

  if not found then
    return false;
  end if;
  if v_format.estado = 'ACTIVO' then
    return false;
  end if;

  v_previous_state := v_format.estado;

  perform set_config(
    'app.format_workflow_action',
    case
      when v_previous_state = 'FINALIZADO' then 'reopen_finalized'
      else 'reopen_ready'
    end,
    true
  );

  update public.formatos
  set
    estado = 'ACTIVO',
    fecha_salida =
      case when coalesce(p_keep_exit_date, false) then fecha_salida else null end,
    labor_confirmed_amount =
      case
        when coalesce(p_keep_exit_date, false) then labor_confirmed_amount
        else null
      end,
    labor_confirmed_at =
      case
        when coalesce(p_keep_exit_date, false) then labor_confirmed_at
        else null
      end,
    labor_confirmed_by =
      case
        when coalesce(p_keep_exit_date, false) then labor_confirmed_by
        else null
      end
  where id = p_format_id;

  delete from public.formatos_globales where id = v_format.folio;
  delete from public.settlement_deferrals
  where format_id = p_format_id and resolved_at is null;

  insert into public.format_state_transitions(
    format_id, from_state, to_state, reason, changed_by
  ) values (
    p_format_id,
    v_previous_state,
    'ACTIVO',
    nullif(trim(coalesce(p_reason, '')), ''),
    auth.uid()
  );

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reopen_finalized_format(p_format_id uuid, p_reason text)
 RETURNS formatos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_format public.formatos;
  v_start date;
  v_end date;
begin
  if not public.is_current_user_admin() then
    raise exception 'Solo un administrador puede devolver un formato al taller';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 5 then
    raise exception 'Indica un motivo de al menos 5 caracteres';
  end if;

  select * into v_format
  from public.formatos
  where id = p_format_id and deleted_at is null;

  if not found then
    raise exception 'Formato no encontrado';
  end if;
  if v_format.estado = 'ACTIVO' then
    raise exception 'El formato ya está En Taller';
  end if;
  if v_format.estado = 'LISTO' then
    raise exception 'Use reopen_ready_format para un formato LISTO';
  end if;

  select ws.start_date, ws.end_date
  into v_start, v_end
  from public.settlement_items si
  join public.weekly_settlements ws on ws.id = si.settlement_id
  where si.format_id = p_format_id
    and coalesce(si.is_advance, false) = false
    and ws.deleted_at is null
  order by ws.end_date desc
  limit 1;

  if found then
    raise exception
      'El formato ya fue liquidado (% a %). Elimina esa liquidación para devolverlo al taller.',
      to_char(v_start, 'DD/MM/YYYY'),
      to_char(v_end, 'DD/MM/YYYY');
  end if;

  perform public.send_format_back_to_workshop(p_format_id, p_reason, false);

  select * into v_format from public.formatos where id = p_format_id;
  return v_format;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.listar_facturas_v2(p_status text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_only_balance boolean DEFAULT false, p_legacy_scope text DEFAULT 'all'::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_has_pdf boolean DEFAULT NULL::boolean)
 RETURNS TABLE(id bigint, id_formato text, precio_factura numeric, pagado numeric, debe numeric, factura_pdf text, estado text, cliente text, created_at timestamp with time zone, placa text, is_legacy boolean, is_read_only boolean, can_register_payment boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_search text := null;
  v_scope text := lower(coalesce(nullif(trim(p_legacy_scope), ''), 'all'));
begin
  if not private.factura_v2_is_admin() then
    raise exception 'Solo un administrador puede consultar facturas' using errcode = '42501';
  end if;

  if nullif(trim(p_search), '') is not null then
    v_search := '%' || replace(replace(trim(p_search), '%', '\%'), '_', '\_') || '%';
  end if;

  if v_scope not in ('all', 'legacy', 'new') then
    raise exception 'El alcance historico no es valido' using errcode = '22023';
  end if;

  return query
  select
    f.id,
    f.id_formato,
    f.precio_factura,
    f.pagado,
    f.debe,
    f.factura_pdf,
    f.estado,
    coalesce(f.cliente, ''),
    f.created_at,
    fo.placa,
    private.factura_v2_is_legacy(f.created_at),
    private.factura_v2_is_legacy(f.created_at),
    coalesce(f.debe, 0) > 0
  from public.facturas f
  left join public.formatos fo on fo.clave_key = f.id_formato
  where (
    nullif(trim(p_status), '') is null
    or upper(trim(p_status)) = 'TODAS'
    or upper(f.estado) = upper(trim(p_status))
  )
  and (
    v_search is null
    or coalesce(f.cliente, '') ilike v_search escape '\'
    or coalesce(f.id_formato, '') ilike v_search escape '\'
    or coalesce(fo.placa, '') ilike v_search escape '\'
  )
  and (p_from is null or f.created_at::date >= p_from)
  and (p_to is null or f.created_at::date <= p_to)
  and (not coalesce(p_only_balance, false) or coalesce(f.debe, 0) > 0)
  and (p_has_pdf is null or (p_has_pdf and nullif(trim(f.factura_pdf), '') is not null) or (not p_has_pdf and nullif(trim(f.factura_pdf), '') is null))
  and (
    v_scope = 'all'
    or (v_scope = 'legacy' and private.factura_v2_is_legacy(f.created_at))
    or (v_scope = 'new' and not private.factura_v2_is_legacy(f.created_at))
  )
  order by f.created_at desc nulls last, f.id desc
  limit greatest(1, least(coalesce(p_limit, 25), 100))
  offset greatest(coalesce(p_offset, 0), 0);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finalize_due_settlement_formats()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_hoy date := (now() at time zone 'America/Bogota')::date;
  v_active_environment uuid := public.current_test_environment_id();
  v_promovidos integer := 0;
begin
  perform set_config('app.format_workflow_action', 'finalize_due', true);

  with debidos as (
    select distinct f.id
    from public.formatos f
    join public.settlement_items si
      on si.format_id = f.id
     and coalesce(si.is_advance, false) = false
     and si.test_environment_id is not distinct from v_active_environment
    join public.weekly_settlements ws
      on ws.id = si.settlement_id
     and ws.deleted_at is null
     and ws.test_environment_id is not distinct from v_active_environment
    where f.deleted_at is null
      and f.estado = 'LISTO'
      and f.test_environment_id is not distinct from v_active_environment
      and coalesce(ws.formats_finalize_on, ws.end_date + 2) <= v_hoy
  ),
  promovidos as (
    update public.formatos f
    set estado = 'FINALIZADO'
    from debidos d
    where f.id = d.id
      and f.test_environment_id is not distinct from v_active_environment
    returning f.id
  )
  insert into public.format_state_transitions(
    format_id, from_state, to_state, reason, changed_by
  )
  select
    p.id,
    'LISTO',
    'FINALIZADO',
    'Cierre automático al iniciar la semana siguiente',
    auth.uid()
  from promovidos p;

  get diagnostics v_promovidos = row_count;
  return v_promovidos;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.capture_weekly_goal_on_settlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_active_environment uuid := public.current_test_environment_id();
  v_goal numeric;
begin
  if v_active_environment is null then
    -- Production keeps the normal lifecycle of the real weekly goal.
    update public.weekly_settlement_goals
    set
      settled_at = now(),
      updated_at = now()
    where period_start = new.start_date
      and period_end = new.end_date
    returning labor_goal into v_goal;
  else
    -- Test settlements may copy the target into their isolated snapshot, but
    -- they must never settle or delete the production goal.
    select labor_goal
    into v_goal
    from public.weekly_settlement_goals
    where period_start = new.start_date
      and period_end = new.end_date;
  end if;

  new.weekly_labor_goal := coalesce(new.weekly_labor_goal, v_goal);
  new.weekly_labor_actual := coalesce(
    new.confirmed_labor_total,
    new.total_labor_gross,
    0
  );

  if v_active_environment is null then
    delete from public.weekly_settlement_goals
    where settled_at is not null
      and period_end < date_trunc('week', current_date)::date;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.restore_weekly_settlement(p_settlement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_settlement public.weekly_settlements;
  v_conflict text;
  v_item public.settlement_items_voided;
  v_format public.formatos;
  v_reason text;
  v_pending integer;
  v_restored_items integer := 0;
  v_restored_formats integer := 0;
  v_skipped_items integer := 0;
  v_restored_deferrals integer := 0;
  v_previous_state text;
  v_fecha_salida date;
begin
  if not public.is_current_user_admin() then
    raise exception 'Solo un administrador puede restaurar liquidaciones';
  end if;

  select * into v_settlement
  from public.weekly_settlements
  where id = p_settlement_id
  for update;

  if not found then
    raise exception 'Liquidación no encontrada';
  end if;

  select count(*) into v_pending
  from public.settlement_items_voided
  where settlement_id = p_settlement_id;

  if v_settlement.deleted_at is null and v_pending = 0 then
    raise exception 'Esta liquidación no está en la papelera';
  end if;

  if exists (
    select 1
    from public.weekly_settlements ws
    where ws.id <> p_settlement_id
      and ws.start_date = v_settlement.start_date
      and ws.end_date = v_settlement.end_date
      and ws.deleted_at is null
  ) then
    raise exception
      'Ya existe otra liquidación vigente para el periodo % a %. Elimínala antes de restaurar esta.',
      to_char(v_settlement.start_date, 'DD/MM/YYYY'),
      to_char(v_settlement.end_date, 'DD/MM/YYYY');
  end if;

  select string_agg(distinct coalesce(f.folio, f.id::text), ', ')
  into v_conflict
  from public.settlement_items_voided v
  join public.formatos f on f.id = v.format_id
  join public.settlement_items si on si.format_id = v.format_id
  join public.weekly_settlements ws on ws.id = si.settlement_id
  where v.settlement_id = p_settlement_id
    and coalesce(v.is_advance, false) = false
    and coalesce(si.is_advance, false) = false
    and ws.deleted_at is null;

  if v_conflict is not null then
    raise exception
      'No se puede restaurar: estos formatos ya se liquidaron en otro cierre (%). Elimina esa liquidación primero.',
      v_conflict;
  end if;

  v_reason := format(
    'Liquidación restaurada (%s a %s)',
    to_char(v_settlement.start_date, 'DD/MM/YYYY'),
    to_char(v_settlement.end_date, 'DD/MM/YYYY')
  );

  for v_item in
    select *
    from public.settlement_items_voided
    where settlement_id = p_settlement_id
      and coalesce(is_advance, false) = false
    order by created_at
  loop
    select * into v_format
    from public.formatos
    where id = v_item.format_id and deleted_at is null
    for update;

    if not found
       or v_format.estado = 'FINALIZADO'
       or coalesce(v_item.format_previous_state, 'FINALIZADO') <> 'FINALIZADO' then
      continue;
    end if;

    v_previous_state := v_format.estado;

    v_fecha_salida := least(
      coalesce(
        v_item.format_fecha_salida::date,
        v_item.created_at::date,
        v_settlement.end_date
      ),
      v_settlement.end_date
    );

    perform set_config('app.format_workflow_action', 'restore_settlement', true);

    -- Manda lo que el formato dice hoy: si se corrigió mientras estaba en el
    -- taller, restaurar no puede resucitar el importe viejo.
    update public.formatos
    set
      estado = 'FINALIZADO',
      fecha_salida = v_fecha_salida,
      labor_confirmed_amount = coalesce(
        nullif(costo_mano_obra, 0),
        v_item.format_labor_confirmed_amount,
        nullif(v_item.original_amount, 0)
      ),
      labor_confirmed_at = coalesce(
        v_item.format_labor_confirmed_at,
        v_item.created_at,
        now()
      ),
      labor_confirmed_by = coalesce(
        v_item.format_labor_confirmed_by,
        v_settlement.created_by,
        auth.uid()
      )
    where id = v_item.format_id
    returning * into v_format;

    insert into public.format_state_transitions(
      format_id, from_state, to_state, reason, changed_by
    ) values (
      v_item.format_id,
      v_previous_state,
      'FINALIZADO',
      v_reason,
      auth.uid()
    );

    v_restored_formats := v_restored_formats + 1;
  end loop;

  with vueltos as (
    delete from public.settlement_items_voided v
    where v.settlement_id = p_settlement_id
      and exists (
        select 1 from public.formatos f
        where f.id = v.format_id and f.deleted_at is null
      )
    returning v.*
  )
  insert into public.settlement_items(
    id,
    settlement_id,
    format_id,
    original_amount,
    adjusted_amount,
    previous_advances,
    is_advance,
    notes,
    created_at
  )
  select
    r.id,
    r.settlement_id,
    r.format_id,
    case
      when coalesce(r.is_advance, false) then r.original_amount
      else coalesce(nullif(f.labor_confirmed_amount, 0), r.original_amount)
    end,
    case
      when coalesce(r.is_advance, false) then r.adjusted_amount
      else greatest(
        coalesce(nullif(f.labor_confirmed_amount, 0), r.original_amount)
          - coalesce(r.previous_advances, 0),
        0
      )
    end,
    r.previous_advances,
    r.is_advance,
    r.notes,
    coalesce(r.created_at, now())
  from vueltos r
  left join public.formatos f on f.id = r.format_id
  on conflict (id) do nothing;
  get diagnostics v_restored_items = row_count;

  select count(*)
  into v_skipped_items
  from public.settlement_items_voided
  where settlement_id = p_settlement_id;

  with aplazamientos as (
    delete from public.settlement_deferrals_voided d
    where d.settlement_id = p_settlement_id
      and exists (
        select 1 from public.formatos f
        where f.id = d.format_id and f.deleted_at is null
      )
    returning d.*
  ),
  insertados as (
    insert into public.settlement_deferrals(
      id, format_id, period_start, period_end, reason,
      created_by, created_at, resolved_at, resolved_settlement_id
    )
    select
      d.id,
      d.format_id,
      d.period_start,
      d.period_end,
      d.reason,
      d.created_by,
      coalesce(d.created_at, now()),
      coalesce(d.resolved_at, v_settlement.created_at, now()),
      p_settlement_id
    from aplazamientos d
    on conflict (id) do update set
      resolved_at = excluded.resolved_at,
      resolved_settlement_id = excluded.resolved_settlement_id
    returning 1
  )
  select count(*) into v_restored_deferrals from insertados;

  if v_settlement.deleted_at is not null then
    perform set_config('app.settlement_action', 'restore', true);
    update public.weekly_settlements
    set
      deleted_at = null,
      deleted_by = null
    where id = p_settlement_id;
  end if;

  -- Los pagos ya registrados a cada trabajador no se tocan: eso se pagó así.
  perform public.recalculate_settlement_totals(p_settlement_id);

  return jsonb_build_object(
    'id', p_settlement_id,
    'restored_items', v_restored_items,
    'restored_formats', v_restored_formats,
    'skipped_items', v_skipped_items,
    'restored_deferrals', v_restored_deferrals
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.listar_facturas_v2(p_status text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_only_balance boolean DEFAULT false, p_legacy_scope text DEFAULT 'all'::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0)
 RETURNS TABLE(id bigint, id_formato text, precio_factura numeric, pagado numeric, debe numeric, factura_pdf text, estado text, cliente text, created_at timestamp with time zone, placa text, is_legacy boolean, is_read_only boolean, can_register_payment boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_search text := null;
  v_scope text := lower(coalesce(nullif(trim(p_legacy_scope), ''), 'all'));
begin
  if not private.factura_v2_is_admin() then
    raise exception 'Solo un administrador puede consultar facturas' using errcode = '42501';
  end if;

  if nullif(trim(p_search), '') is not null then
    v_search := '%' || replace(replace(trim(p_search), '%', '\%'), '_', '\_') || '%';
  end if;

  if v_scope not in ('all', 'legacy', 'new') then
    raise exception 'El alcance historico no es valido' using errcode = '22023';
  end if;

  return query
  select
    f.id,
    f.id_formato,
    f.precio_factura,
    f.pagado,
    f.debe,
    f.factura_pdf,
    f.estado,
    coalesce(f.cliente, ''),
    f.created_at,
    fo.placa,
    private.factura_v2_is_legacy(f.created_at),
    private.factura_v2_is_legacy(f.created_at),
    coalesce(f.debe, 0) > 0
  from public.facturas f
  left join public.formatos fo on fo.clave_key = f.id_formato
  where (
    nullif(trim(p_status), '') is null
    or upper(trim(p_status)) = 'TODAS'
    or upper(f.estado) = upper(trim(p_status))
  )
  and (
    v_search is null
    or coalesce(f.cliente, '') ilike v_search escape '\'
    or coalesce(f.id_formato, '') ilike v_search escape '\'
    or coalesce(fo.placa, '') ilike v_search escape '\'
  )
  and (p_from is null or f.created_at::date >= p_from)
  and (p_to is null or f.created_at::date <= p_to)
  and (not coalesce(p_only_balance, false) or coalesce(f.debe, 0) > 0)
  and (
    v_scope = 'all'
    or (v_scope = 'legacy' and private.factura_v2_is_legacy(f.created_at))
    or (v_scope = 'new' and not private.factura_v2_is_legacy(f.created_at))
  )
  order by f.created_at desc nulls last, f.id desc
  limit greatest(1, least(coalesce(p_limit, 25), 100))
  offset greatest(coalesce(p_offset, 0), 0);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.desvincular_factura_pdf_v2(p_id_formato text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_format public.formatos%rowtype;
  v_invoice public.facturas%rowtype;
  v_format_result jsonb;
begin
  if not private.factura_v2_is_admin() then
    raise exception 'Solo un administrador puede desvincular facturas'
      using errcode = '42501';
  end if;

  select * into v_format
  from public.formatos
  where clave_key = nullif(trim(p_id_formato), '');
  if not found then
    raise exception 'El formato no existe' using errcode = 'P0002';
  end if;

  select * into v_invoice
  from public.facturas
  where id_formato = v_format.clave_key
  for update;

  perform set_config('app.invoice_v2_internal', 'true', true);
  update public.formatos
  set url_documento = null
  where id = v_format.id
  returning to_jsonb(formatos) into v_format_result;

  if v_invoice.id is not null then
    update public.facturas
    set factura_pdf = null
    where id = v_invoice.id;
  end if;

  return jsonb_build_object(
    'formato', coalesce(v_format_result, to_jsonb(v_format)),
    'factura', case when v_invoice.id is null then null else to_jsonb(v_invoice) end
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.obtener_factura_por_formato_v2(p_id_formato text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_invoice public.facturas%rowtype;
begin
  if auth.uid() is null
     and current_setting('request.jwt.claim.role', true) <> 'service_role' then
    raise exception 'Usuario no autenticado' using errcode = '42501';
  end if;

  select * into v_invoice
  from public.facturas
  where id_formato = nullif(trim(p_id_formato), '');

  if not found then
    return null;
  end if;

  return to_jsonb(v_invoice) || jsonb_build_object(
    'is_legacy', private.factura_v2_is_legacy(v_invoice.created_at),
    'is_read_only', private.factura_v2_is_legacy(v_invoice.created_at),
    'can_register_payment', coalesce(v_invoice.debe, 0) > 0
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.registrar_abono_v2(p_monto numeric, p_fecha date, p_id_formato text, p_origen text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_invoice public.facturas%rowtype;
  v_abono public.abonos%rowtype;
  v_legacy boolean;
  v_new_paid numeric;
  v_new_debt numeric;
  v_id_abono text;
  v_origin text;
begin
  if not private.factura_v2_is_admin() then
    raise exception 'Solo un administrador puede registrar abonos' using errcode = '42501';
  end if;
  if p_monto is null or p_monto <= 0 then
    raise exception 'El monto del abono debe ser mayor que cero' using errcode = '22023';
  end if;
  if p_fecha is null or p_fecha > current_date then
    raise exception 'La fecha del abono no puede ser futura' using errcode = '22023';
  end if;

  -- El origen ya no es obligatorio: si no viene (o viene vacío) se guarda
  -- como null, igual que los abonos históricos. Si viene, se sigue
  -- validando que sea un valor conocido.
  v_origin := nullif(upper(trim(p_origen)), '');
  if v_origin is not null and v_origin <> 'REGISTRADO_APP' then
    raise exception 'El origen del abono no es válido' using errcode = '22023';
  end if;

  select * into v_invoice
  from public.facturas
  where id_formato = nullif(trim(p_id_formato), '')
  for update;

  if not found then
    raise exception 'La factura no existe' using errcode = 'P0002';
  end if;

  v_legacy := private.factura_v2_is_legacy(v_invoice.created_at);
  if coalesce(v_invoice.debe, 0) <= 0 then
    raise exception 'La factura no tiene saldo disponible' using errcode = '22003';
  end if;
  if p_monto > v_invoice.debe then
    raise exception 'El abono no puede superar el saldo pendiente' using errcode = '22003';
  end if;

  v_id_abono := 'AB-' || lpad(nextval('public.abono_folio_seq')::text, 3, '0');
  perform set_config('app.invoice_v2_internal', 'true', true);
  insert into public.abonos (id_abono, monto, fecha, id_factura, origen)
  values (v_id_abono, p_monto, p_fecha, v_invoice.id_formato, v_origin)
  returning * into v_abono;

  if v_legacy then
    v_new_paid := coalesce(v_invoice.pagado, 0) + p_monto;
    v_new_debt := greatest(coalesce(v_invoice.debe, 0) - p_monto, 0);
  else
    select coalesce(sum(a.monto), 0)
    into v_new_paid
    from public.abonos a
    where a.id_factura = v_invoice.id_formato;
    v_new_debt := greatest(coalesce(v_invoice.precio_factura, 0) - v_new_paid, 0);
  end if;

  update public.facturas
  set pagado = v_new_paid,
      debe = v_new_debt,
      estado = case
        when v_legacy then case when v_new_debt = 0 then 'PAGADO' else 'PENDIENTE' end
        else private.factura_v2_state(v_invoice.precio_factura, v_new_paid)
      end
  where id = v_invoice.id
  returning * into v_invoice;

  return jsonb_build_object('factura', to_jsonb(v_invoice), 'abono', to_jsonb(v_abono));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_repuesto_with_catalog_atomic(p_id uuid, p_data jsonb, p_catalog_description text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_catalog jsonb;
  v_enriched_data jsonb;
begin
  if jsonb_typeof(p_data) <> 'object' then
    raise exception 'Los datos del repuesto no tienen un formato valido'
      using errcode = '22023';
  end if;

  v_catalog := public.create_catalogo_repuesto_atomic(p_catalog_description);
  v_enriched_data := p_data || jsonb_build_object(
    'id_identificacion', v_catalog ->> 'id_identificacion',
    'descripcion', v_catalog ->> 'descripcion'
  );

  return public.update_repuesto_atomic(p_id, v_enriched_data);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.is_current_user_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select exists (select 1 from public.profiles where id = auth.uid() and lower(role) = 'admin' and is_active = true); $function$
;

CREATE OR REPLACE FUNCTION public.close_weekly_settlement(p_start_date date, p_end_date date, p_wage_fund_percentage numeric, p_items jsonb, p_workers jsonb, p_total_bonus numeric DEFAULT 0, p_deferrals jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_active_environment uuid := public.current_test_environment_id();
  v_settlement_id uuid;
  v_item jsonb;
  v_worker jsonb;
  v_deferral jsonb;
  v_format public.formatos;
  v_is_advance boolean;
  v_previous_advances numeric;
  v_adjusted numeric;
  v_total_liquidated numeric := 0;
  v_total_gross numeric := 0;
  v_confirmed_total numeric := 0;
  v_confirmed_count integer := 0;
  v_referrals numeric := 0;
  v_wage_fund_gross numeric;
  v_wage_fund_base numeric;
  v_shop_profit numeric;
  v_missing integer;
  v_finalize_on date;
begin
  if not public.is_current_user_admin() then
    raise exception 'Solo un administrador puede cerrar liquidaciones';
  end if;

  perform public.finalize_due_settlement_formats();

  if p_end_date < p_start_date then
    raise exception 'El periodo de liquidación no es válido';
  end if;
  if p_wage_fund_percentage < 0 or p_wage_fund_percentage > 100 then
    raise exception 'El porcentaje del fondo debe estar entre 0 y 100';
  end if;
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_workers, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_deferrals, '[]'::jsonb)) <> 'array' then
    raise exception 'Los items, trabajadores y aplazamientos deben ser listas';
  end if;
  if exists (
    select 1
    from public.weekly_settlements
    where start_date = p_start_date
      and end_date = p_end_date
      and deleted_at is null
      and test_environment_id is not distinct from v_active_environment
  ) then
    raise exception 'Ya existe una liquidación para este periodo';
  end if;

  select count(*) into v_missing
  from public.formatos f
  where f.estado = 'LISTO'
    and f.deleted_at is null
    and f.test_environment_id is not distinct from v_active_environment
    and f.fecha_salida <= p_end_date
    and not exists (
      select 1
      from public.settlement_items si
      join public.weekly_settlements ws on ws.id = si.settlement_id
      where si.format_id = f.id
        and si.test_environment_id is not distinct from v_active_environment
        and ws.test_environment_id is not distinct from v_active_environment
        and coalesce(si.is_advance, false) = false
        and ws.deleted_at is null
    )
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) i
      where (i->>'format_id')::uuid = f.id
        and coalesce((i->>'is_advance')::boolean, false) = false
    )
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(p_deferrals, '[]'::jsonb)) d
      where (d->>'format_id')::uuid = f.id
        and length(trim(coalesce(d->>'reason', ''))) >= 5
    );
  if v_missing > 0 then
    raise exception
      'Todos los formatos LISTO deben liquidarse o aplazarse con motivo (% pendientes)',
      v_missing;
  end if;

  for v_item in
    select value from jsonb_array_elements(coalesce(p_items, '[]'::jsonb))
  loop
    select * into v_format
    from public.formatos
    where id = (v_item->>'format_id')::uuid
      and deleted_at is null
      and test_environment_id is not distinct from v_active_environment
    for update;
    if not found then
      raise exception 'Uno de los formatos seleccionados no pertenece al entorno actual';
    end if;

    v_is_advance := coalesce((v_item->>'is_advance')::boolean, false);
    select coalesce(sum(adjusted_amount), 0) into v_previous_advances
    from public.settlement_items
    where format_id = v_format.id
      and test_environment_id is not distinct from v_active_environment
      and coalesce(is_advance, false) = true;

    if v_is_advance then
      if v_format.estado <> 'ACTIVO' then
        raise exception 'Los adelantos solo se permiten para formatos ACTIVO';
      end if;
      v_adjusted := coalesce((v_item->>'adjusted_amount')::numeric, 0);
      if v_adjusted <= 0
         or v_adjusted > greatest(
           coalesce(v_format.costo_mano_obra, 0) - v_previous_advances,
           0
         ) then
        raise exception 'El adelanto del formato % no es válido', v_format.folio;
      end if;
      v_total_gross := v_total_gross + coalesce(v_format.costo_mano_obra, 0);
    else
      if v_format.estado <> 'LISTO' then
        raise exception 'Solo los formatos LISTO pueden liquidarse por completo';
      end if;
      if v_format.labor_confirmed_amount is null then
        raise exception 'El formato % no tiene mano de obra confirmada', v_format.folio;
      end if;
      if exists (
        select 1
        from public.settlement_items
        where format_id = v_format.id
          and test_environment_id is not distinct from v_active_environment
          and coalesce(is_advance, false) = false
      ) then
        raise exception 'El formato % ya fue liquidado por completo', v_format.folio;
      end if;
      v_adjusted := greatest(
        v_format.labor_confirmed_amount - v_previous_advances,
        0
      );
      v_total_gross := v_total_gross + v_format.labor_confirmed_amount;
      v_confirmed_total := v_confirmed_total + v_format.labor_confirmed_amount;
      v_confirmed_count := v_confirmed_count + 1;
    end if;

    v_total_liquidated := v_total_liquidated + v_adjusted;
    if nullif(trim(coalesce(v_format.referido_por, '')), '') is not null then
      v_referrals := v_referrals + (v_adjusted * 0.15);
    end if;
  end loop;

  v_wage_fund_gross := v_total_liquidated * (p_wage_fund_percentage / 100);
  v_wage_fund_base := greatest(v_wage_fund_gross - v_referrals, 0);
  v_shop_profit := v_total_liquidated - v_wage_fund_gross;
  if v_referrals > v_wage_fund_gross then
    raise exception 'Las comisiones por referidos superan el fondo disponible';
  end if;

  v_finalize_on :=
    date_trunc('week', (now() at time zone 'America/Bogota')::date)::date + 7;

  insert into public.weekly_settlements(
    start_date, end_date, total_labor_gross, total_labor_liquidated,
    wage_fund_percentage, wage_fund_total, shop_profit, created_by,
    total_bonus, total_referral_commission, confirmed_labor_total,
    confirmed_format_count, formats_finalize_on
  )
  values (
    p_start_date, p_end_date, v_total_gross, v_total_liquidated,
    p_wage_fund_percentage, v_wage_fund_base, v_shop_profit, auth.uid(),
    coalesce(p_total_bonus, 0), v_referrals, v_confirmed_total,
    v_confirmed_count, v_finalize_on
  )
  returning id into v_settlement_id;

  for v_item in
    select value from jsonb_array_elements(coalesce(p_items, '[]'::jsonb))
  loop
    select * into v_format
    from public.formatos
    where id = (v_item->>'format_id')::uuid
      and test_environment_id is not distinct from v_active_environment
    for update;
    v_is_advance := coalesce((v_item->>'is_advance')::boolean, false);
    select coalesce(sum(adjusted_amount), 0) into v_previous_advances
    from public.settlement_items
    where format_id = v_format.id
      and test_environment_id is not distinct from v_active_environment
      and coalesce(is_advance, false) = true;

    if v_is_advance then
      v_adjusted := (v_item->>'adjusted_amount')::numeric;
    else
      v_adjusted := greatest(
        v_format.labor_confirmed_amount - v_previous_advances,
        0
      );
    end if;

    insert into public.settlement_items(
      settlement_id, format_id, original_amount, adjusted_amount,
      previous_advances, is_advance, notes
    )
    values (
      v_settlement_id, v_format.id,
      case when v_is_advance then coalesce(v_format.costo_mano_obra, 0)
           else v_format.labor_confirmed_amount end,
      v_adjusted, v_previous_advances, v_is_advance,
      nullif(trim(v_item->>'notes'), '')
    );

    if not v_is_advance then
      update public.settlement_deferrals
      set resolved_at = now(), resolved_settlement_id = v_settlement_id
      where format_id = v_format.id
        and test_environment_id is not distinct from v_active_environment
        and resolved_at is null;
    end if;
  end loop;

  for v_worker in
    select value from jsonb_array_elements(coalesce(p_workers, '[]'::jsonb))
  loop
    if length(trim(coalesce(v_worker->>'worker_name', ''))) = 0 then
      raise exception 'Cada pago debe tener un trabajador';
    end if;
    insert into public.settlement_worker_payments(
      settlement_id, worker_name, percentage_share, payment_amount,
      bonus_amount, bonus_percentage, referral_commission
    )
    values (
      v_settlement_id, trim(v_worker->>'worker_name'),
      coalesce((v_worker->>'percentage_share')::numeric, 0),
      coalesce((v_worker->>'payment_amount')::numeric, 0),
      coalesce((v_worker->>'bonus_amount')::numeric, 0),
      coalesce((v_worker->>'bonus_percentage')::numeric, 0),
      coalesce((v_worker->>'referral_commission')::numeric, 0)
    );
  end loop;

  for v_deferral in
    select value from jsonb_array_elements(coalesce(p_deferrals, '[]'::jsonb))
  loop
    if length(trim(coalesce(v_deferral->>'reason', ''))) < 5 then
      raise exception 'Cada aplazamiento debe incluir un motivo';
    end if;
    if not exists (
      select 1
      from public.formatos
      where id = (v_deferral->>'format_id')::uuid
        and estado = 'LISTO'
        and deleted_at is null
        and test_environment_id is not distinct from v_active_environment
    ) then
      raise exception 'Solo se pueden aplazar formatos LISTO del entorno actual';
    end if;
    insert into public.settlement_deferrals(
      format_id, period_start, period_end, reason, created_by
    )
    values (
      (v_deferral->>'format_id')::uuid, p_start_date, p_end_date,
      trim(v_deferral->>'reason'), auth.uid()
    )
    on conflict (format_id) where resolved_at is null
    do update set
      period_start = excluded.period_start,
      period_end = excluded.period_end,
      reason = excluded.reason,
      created_by = excluded.created_by,
      created_at = now();
  end loop;

  return jsonb_build_object(
    'id', v_settlement_id,
    'confirmed_labor_total', v_confirmed_total,
    'confirmed_format_count', v_confirmed_count,
    'total_labor_liquidated', v_total_liquidated,
    'formats_finalize_on', v_finalize_on
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.adjuntar_factura_pdf_v2(p_id_formato text, p_factura_pdf text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_invoice public.facturas%rowtype;
  v_format public.formatos%rowtype;
  v_total numeric;
  v_invoice_found boolean;
begin
  if not private.factura_v2_is_admin() then
    raise exception 'Solo un administrador puede adjuntar facturas' using errcode = '42501';
  end if;
  if nullif(trim(p_factura_pdf), '') is null then
    raise exception 'La URL del PDF es obligatoria' using errcode = '22023';
  end if;

  select * into v_format
  from public.formatos
  where clave_key = nullif(trim(p_id_formato), '');
  if not found then
    raise exception 'El formato no existe' using errcode = 'P0002';
  end if;

  select * into v_invoice
  from public.facturas
  where id_formato = v_format.clave_key
  for update;
  v_invoice_found := found;

  perform set_config('app.invoice_v2_internal', 'true', true);
  if not v_invoice_found then
    v_total := greatest(coalesce(v_format.costo_total, 0), 0);
    insert into public.facturas (
      id_formato, precio_factura, pagado, debe, factura_pdf, estado, cliente
    ) values (
      v_format.clave_key,
      v_total,
      0,
      v_total,
      p_factura_pdf,
      private.factura_v2_state(v_total, 0),
      coalesce(v_format.nombre_cliente, '')
    ) returning * into v_invoice;
  else
    -- Solo el documento. Una factura historica mantiene su cuenta intacta.
    update public.facturas
    set factura_pdf = p_factura_pdf
    where id = v_invoice.id
    returning * into v_invoice;
  end if;

  update public.formatos
  set url_documento = p_factura_pdf
  where id = v_format.id;

  return to_jsonb(v_invoice);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_new_format(p_format_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_number integer;
  v_placa text;
  v_is_development boolean := coalesce(
    nullif(p_format_data ->> 'is_development', '')::boolean,
    false
  );
  v_created public.formatos;
begin
  if auth.uid() is null then
    raise exception 'Usuario no autenticado' using errcode = '42501';
  end if;

  if v_is_development and not public.is_current_user_admin() then
    raise exception 'Solo un administrador puede crear formatos de desarrollo'
      using errcode = '42501';
  end if;

  v_placa := upper(trim(coalesce(p_format_data ->> 'placa', '')));
  if length(v_placa) < 6 then
    raise exception 'La placa no es valida' using errcode = '22023';
  end if;

  if nullif(trim(p_format_data ->> 'marca'), '') is null
     or nullif(trim(p_format_data ->> 'tipo_vehiculo'), '') is null then
    raise exception 'La marca y el tipo de vehiculo son requeridos'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('vehicle:' || v_placa, 0));

  if not v_is_development and not exists (
    select 1
    from public.vehiculos_registrados
    where upper(trim(placa)) = v_placa
  ) then
    insert into public.vehiculos_registrados (placa, marca, tipo_vehiculo)
    values (
      v_placa,
      trim(p_format_data ->> 'marca'),
      trim(p_format_data ->> 'tipo_vehiculo')
    );
  end if;

  v_number := public.get_next_clave_key_number();

  insert into public.formatos (
    folio,
    clave_key,
    fecha_entrada,
    tipo_formato,
    recibido_por,
    placa,
    marca,
    tipo_vehiculo,
    modelo,
    nombre_cliente,
    nombre_conductor,
    telefono_contacto,
    kilometraje,
    trabajos_realizados,
    clave_control,
    costo_mano_obra,
    estado,
    costo_repuestos,
    observaciones,
    rol_creador,
    fotos_vehiculo,
    referido_por,
    is_development,
    created_by
  ) values (
    'FL-' || v_number,
    'F-' || v_number,
    coalesce(
      nullif(p_format_data ->> 'fecha_entrada', '')::timestamptz::date,
      current_date
    ),
    nullif(trim(p_format_data ->> 'tipo_formato'), ''),
    nullif(trim(p_format_data ->> 'recibido_por'), ''),
    v_placa,
    trim(p_format_data ->> 'marca'),
    trim(p_format_data ->> 'tipo_vehiculo'),
    nullif(trim(p_format_data ->> 'modelo'), '')::numeric,
    nullif(trim(p_format_data ->> 'nombre_cliente'), ''),
    nullif(trim(p_format_data ->> 'nombre_conductor'), ''),
    nullif(trim(p_format_data ->> 'telefono_contacto'), ''),
    nullif(trim(p_format_data ->> 'kilometraje'), '')::numeric,
    nullif(trim(p_format_data ->> 'trabajos_realizados'), ''),
    nullif(trim(p_format_data ->> 'clave_control'), ''),
    coalesce(nullif(p_format_data ->> 'costo_mano_obra', '')::numeric, 0),
    coalesce(nullif(trim(p_format_data ->> 'estado'), ''), 'ACTIVO'),
    coalesce(nullif(p_format_data ->> 'costo_repuestos', '')::numeric, 0),
    nullif(trim(p_format_data ->> 'observaciones'), ''),
    nullif(trim(p_format_data ->> 'rol_creador'), ''),
    coalesce(p_format_data -> 'fotos_vehiculo', '{}'::jsonb),
    nullif(trim(p_format_data ->> 'referido_por'), ''),
    v_is_development,
    auth.uid()
  )
  returning * into v_created;

  return to_jsonb(v_created);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.permanently_delete_formato(p_folio text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_format public.formatos%rowtype;
begin
  if not private.factura_v2_is_admin() then
    raise exception 'Solo un administrador puede eliminar formatos'
      using errcode = '42501';
  end if;

  select formato.*
  into v_format
  from public.formatos as formato
  where formato.folio = p_folio
     or formato.clave_key = p_folio
  for update;

  if not found then
    return;
  end if;

  perform public.eliminar_factura_y_abonos_asociados(v_format.clave_key);
  if v_format.folio is distinct from v_format.clave_key then
    perform public.eliminar_factura_y_abonos_asociados(v_format.folio);
  end if;

  delete from public.registro_tiempos
  where formato_folio in (v_format.folio, v_format.clave_key);

  delete from public.trashed_photos
  where formato_id in (
    v_format.id::text,
    v_format.folio,
    v_format.clave_key
  );

  delete from public.deletion_requests
  where lower(entity_type) in ('formato', 'formatos')
    and entity_id in (
      v_format.id::text,
      v_format.folio,
      v_format.clave_key
    );

  delete from public.formatos_globales
  where id in (v_format.folio, v_format.clave_key);

  delete from public.servicios
  where formato_folio in (v_format.folio, v_format.clave_key);

  delete from public.repuestos
  where id_repuesto in (v_format.folio, v_format.clave_key)
     or formato_folio in (v_format.folio, v_format.clave_key);

  delete from public.formatos where id = v_format.id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.exit_format_development_environment(p_delete_data boolean)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  select public.exit_global_test_environment(p_delete_data)
$function$
;

CREATE OR REPLACE FUNCTION public.permanently_delete_formatos(p_folios text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'auth', 'pg_temp'
AS $function$
declare
  v_folio text;
begin
  if not private.factura_v2_is_admin() then
    raise exception 'Solo un administrador puede eliminar formatos'
      using errcode = '42501';
  end if;

  foreach v_folio in array coalesce(p_folios, array[]::text[]) loop
    perform public.permanently_delete_formato(v_folio);
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_repuesto_atomic(p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_quantity integer;
  v_description text;
  v_unit_cost numeric;
  v_origin text;
  v_updated public.repuestos;
begin
  if auth.uid() is null then
    raise exception 'Usuario no autenticado' using errcode = '42501';
  end if;

  v_quantity := nullif(p_data ->> 'cantidad', '')::integer;
  v_description := regexp_replace(
    trim(coalesce(p_data ->> 'descripcion', '')),
    '\s+',
    ' ',
    'g'
  );
  v_unit_cost := nullif(p_data ->> 'costo_unitario', '')::numeric;
  v_origin := upper(trim(coalesce(p_data ->> 'traido_por', '')));

  if v_quantity is null
     or v_quantity <= 0
     or v_quantity > 100000
     or v_description = ''
     or v_unit_cost is null
     or abs(v_unit_cost) > 1000000000000
     or v_origin not in ('TALLER', 'CLIENTE') then
    raise exception 'Los datos del repuesto no son validos'
      using errcode = '22023';
  end if;

  update public.repuestos
  set
    id_identificacion = nullif(trim(p_data ->> 'id_identificacion'), ''),
    descripcion = v_description,
    cantidad = v_quantity,
    costo_unitario = v_unit_cost,
    costo_total_linea = v_quantity * v_unit_cost,
    traido_por = v_origin
  where id = p_id
    and deleted_at is null
  returning * into v_updated;

  if v_updated.id is null then
    raise exception 'El repuesto no existe o fue eliminado'
      using errcode = 'P0002';
  end if;

  return to_jsonb(v_updated);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.recalculate_format_costs_from_repuestos()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_folio text;
  v_folios text[];
  v_parts_total numeric;
begin
  -- The parent cascade will also delete the format, so recalculating it here is
  -- unnecessary and would be rejected after all admin modes are disabled.
  if tg_op = 'DELETE'
     and private.is_global_test_cleanup(old.test_environment_id) then
    return old;
  end if;

  if tg_op = 'DELETE' then
    v_folios := array[old.id_repuesto];
  elsif tg_op = 'UPDATE' then
    v_folios := array[old.id_repuesto, new.id_repuesto];
  else
    v_folios := array[new.id_repuesto];
  end if;

  foreach v_folio in array v_folios loop
    if v_folio is null then
      continue;
    end if;

    select coalesce(sum(repuesto.costo_total_linea), 0)
    into v_parts_total
    from public.repuestos as repuesto
    where repuesto.id_repuesto = v_folio
      and repuesto.deleted_at is null;

    update public.formatos as formato
    set
      costo_repuestos = v_parts_total,
      costo_total = coalesce(formato.costo_mano_obra, 0) + v_parts_total
    where formato.folio = v_folio;

    update public.formatos_globales as formato_global
    set
      precio_repuestos = v_parts_total,
      total = formato.costo_total
    from public.formatos as formato
    where formato.folio = v_folio
      and formato_global.id = v_folio;
  end loop;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_catalogo_repuesto_atomic(p_descripcion text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_description text;
  v_normalized text;
  v_existing public.catalogo_repuestos%rowtype;
  v_created public.catalogo_repuestos%rowtype;
  v_candidate_id text;
begin
  if auth.uid() is null then
    raise exception 'Usuario no autenticado' using errcode = '42501';
  end if;

  v_description := regexp_replace(trim(coalesce(p_descripcion, '')), '\s+', ' ', 'g');
  if v_description = '' or length(v_description) > 300 then
    raise exception 'La descripcion del repuesto no es valida'
      using errcode = '22023';
  end if;

  v_normalized := lower(v_description);

  perform pg_advisory_xact_lock(
    hashtextextended('catalogo_repuestos:' || v_normalized, 0)
  );

  select catalogo.*
  into v_existing
  from public.catalogo_repuestos as catalogo
  where catalogo.deleted_at is null
    and lower(regexp_replace(trim(catalogo.descripcion), '\s+', ' ', 'g')) = v_normalized
  order by catalogo.created_at, catalogo.id
  limit 1;

  if found then
    return to_jsonb(v_existing);
  end if;

  for v_attempt in 1..10 loop
    v_candidate_id := substring(md5(gen_random_uuid()::text), 1, 6);
    begin
      insert into public.catalogo_repuestos (
        id_identificacion,
        descripcion
      )
      values (
        v_candidate_id,
        v_description
      )
      returning * into v_created;

      return to_jsonb(v_created);
    exception
      when unique_violation then
        null;
    end;
  end loop;

  raise exception 'No fue posible generar un identificador unico para el repuesto'
    using errcode = '23505';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.save_repuestos_atomic(p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Usuario no autenticado' using errcode = '42501';
  end if;

  if jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0
     or jsonb_array_length(p_items) > 50 then
    raise exception 'Debes enviar entre 1 y 50 repuestos'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_items) as item(
      id uuid,
      formato_id uuid,
      formato_folio text,
      id_repuesto text,
      id_identificacion text,
      traido_por text,
      cantidad integer,
      descripcion text,
      costo_unitario numeric,
      created_at timestamptz
    )
    where item.id is null
       or item.cantidad is null
       or item.cantidad <= 0
       or item.cantidad > 100000
       or nullif(trim(item.descripcion), '') is null
       or item.costo_unitario is null
       or abs(item.costo_unitario) > 1000000000000
       or upper(trim(coalesce(item.traido_por, ''))) not in ('TALLER', 'CLIENTE')
  ) then
    raise exception 'Uno o mas repuestos contienen datos invalidos'
      using errcode = '22023';
  end if;

  if exists (
    select item.id
    from jsonb_to_recordset(p_items) as item(id uuid)
    group by item.id
    having count(*) > 1
  ) then
    raise exception 'La solicitud contiene identificadores de repuesto repetidos'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_items) as item(
      formato_id uuid,
      formato_folio text,
      id_repuesto text
    )
    left join public.formatos as formato
      on formato.deleted_at is null
     and (
       (item.formato_id is not null and formato.id = item.formato_id)
       or (
         item.formato_id is null
         and formato.folio = item.id_repuesto
         and formato.clave_key = item.formato_folio
       )
     )
    where formato.id is null
  ) then
    raise exception 'La relacion entre el repuesto y el formato no es valida'
      using errcode = '23503';
  end if;

  with raw_input as (
    select *
    from jsonb_to_recordset(p_items) as item(
      id uuid,
      formato_id uuid,
      formato_folio text,
      id_repuesto text,
      id_identificacion text,
      traido_por text,
      cantidad integer,
      descripcion text,
      costo_unitario numeric,
      created_at timestamptz
    )
  ), input as (
    select
      item.id,
      coalesce(formato.clave_key, item.formato_folio) as formato_folio,
      coalesce(formato.folio, item.id_repuesto) as id_repuesto,
      item.id_identificacion,
      item.traido_por,
      item.cantidad,
      item.descripcion,
      item.costo_unitario,
      item.created_at
    from raw_input as item
    left join public.formatos as formato
      on item.formato_id is not null
     and formato.id = item.formato_id
     and formato.deleted_at is null
  ), inserted as (
    insert into public.repuestos (
      id,
      formato_folio,
      id_repuesto,
      id_identificacion,
      traido_por,
      cantidad,
      descripcion,
      costo_unitario,
      costo_total_linea,
      created_at
    )
    select
      item.id,
      trim(item.formato_folio),
      trim(item.id_repuesto),
      nullif(trim(item.id_identificacion), ''),
      upper(trim(item.traido_por)),
      item.cantidad,
      regexp_replace(trim(item.descripcion), '\s+', ' ', 'g'),
      item.costo_unitario,
      item.cantidad * item.costo_unitario,
      coalesce(item.created_at, now())
    from input as item
    on conflict (id) do nothing
    returning *
  ), requested as (
    select inserted.*
    from inserted

    union all

    select existing.*
    from public.repuestos as existing
    join input on input.id = existing.id
    where existing.deleted_at is null
      and not exists (
        select 1
        from inserted
        where inserted.id = existing.id
      )
  )
  select coalesce(jsonb_agg(to_jsonb(requested) order by requested.created_at), '[]')
  into v_result
  from requested;

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.save_repuesto_with_catalog_atomic(p_item jsonb, p_catalog_description text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_catalog jsonb;
  v_saved jsonb;
  v_enriched_item jsonb;
begin
  if jsonb_typeof(p_item) <> 'object' then
    raise exception 'El repuesto no tiene un formato valido'
      using errcode = '22023';
  end if;

  v_catalog := public.create_catalogo_repuesto_atomic(p_catalog_description);
  v_enriched_item := p_item || jsonb_build_object(
    'id_identificacion', v_catalog ->> 'id_identificacion',
    'descripcion', v_catalog ->> 'descripcion'
  );
  v_saved := public.save_repuestos_atomic(jsonb_build_array(v_enriched_item));

  if jsonb_array_length(v_saved) <> 1 then
    raise exception 'No fue posible confirmar el repuesto creado';
  end if;

  return v_saved -> 0;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.reopen_ready_format(p_format_id uuid, p_reason text)
 RETURNS formatos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_format public.formatos;
begin
  if not public.is_current_user_admin() then raise exception 'Solo un administrador puede reabrir un formato'; end if;
  if length(trim(coalesce(p_reason, ''))) < 5 then raise exception 'Indica un motivo de al menos 5 caracteres'; end if;
  select * into v_format from public.formatos where id = p_format_id and deleted_at is null for update;
  if not found then raise exception 'Formato no encontrado'; end if;
  if v_format.estado <> 'LISTO' then raise exception 'Solo un formato LISTO puede reabrirse'; end if;
  if exists (select 1 from public.settlement_items where format_id = p_format_id and coalesce(is_advance, false) = false) then raise exception 'El formato ya fue liquidado y no se puede reabrir'; end if;
  perform set_config('app.format_workflow_action', 'reopen_ready', true);
  update public.formatos set estado = 'ACTIVO', fecha_salida = null, labor_confirmed_amount = null, labor_confirmed_at = null, labor_confirmed_by = null where id = p_format_id returning * into v_format;
  delete from public.formatos_globales where id = v_format.folio;
  delete from public.settlement_deferrals where format_id = p_format_id and resolved_at is null;
  insert into public.format_state_transitions(format_id, from_state, to_state, reason, changed_by) values (p_format_id, 'LISTO', 'ACTIVO', trim(p_reason), auth.uid());
  return v_format;
end; $function$
;

CREATE OR REPLACE FUNCTION public.guard_ready_format_children()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enabled boolean;
  v_row jsonb;
  v_folio text;
  v_estado text;
begin
  select coalesce(value, false)
  into v_enabled
  from public.app_settings
  where key = 'ready_settlement_workflow_enabled';

  if not coalesce(v_enabled, false) then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;

  v_row := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_folio := coalesce(
    nullif(v_row->>'formato_folio', ''),
    nullif(v_row->>'id_repuesto', '')
  );

  if v_folio is not null then
    select estado into v_estado
    from public.formatos
    where folio = v_folio
    limit 1;

    if v_estado in ('LISTO', 'FINALIZADO')
       and not public.is_current_user_admin() then
      raise exception
        'Los servicios y repuestos de un formato que ya salió del taller solo los puede ajustar un administrador';
    end if;
  end if;

  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_format_ready(p_format_id uuid)
 RETURNS formatos
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_format public.formatos;
  v_is_guarantee boolean;
begin
  if auth.uid() is null then
    raise exception 'Debes iniciar sesion';
  end if;
  if not exists (
    select 1 from public.profiles
    where id = auth.uid()
      and is_active = true
      and lower(role) in ('admin', 'empleado')
  ) then
    raise exception 'Tu perfil no puede confirmar formatos';
  end if;

  select * into v_format
  from public.formatos
  where id = p_format_id and deleted_at is null
  for update;

  if not found then
    raise exception 'Formato no encontrado';
  end if;
  if v_format.estado <> 'ACTIVO' then
    raise exception 'Solo un formato ACTIVO puede marcarse como LISTO';
  end if;

  v_is_guarantee := upper(trim(coalesce(v_format.tipo_formato, ''))) = 'GARANTIA';
  if coalesce(v_format.costo_mano_obra, 0) < 0
     or (coalesce(v_format.costo_mano_obra, 0) = 0 and not v_is_guarantee) then
    raise exception 'La mano de obra debe ser mayor que cero';
  end if;

  perform set_config('app.format_workflow_action', 'mark_ready', true);

  update public.formatos
  set
    estado = 'LISTO',
    fecha_salida = coalesce(fecha_salida, current_date),
    labor_confirmed_amount = coalesce(costo_mano_obra, 0),
    labor_confirmed_at = now(),
    labor_confirmed_by = auth.uid()
  where id = p_format_id
  returning * into v_format;

  insert into public.format_state_transitions(
    format_id, from_state, to_state, changed_by
  ) values (p_format_id, 'ACTIVO', 'LISTO', auth.uid());

  insert into public.formatos_globales(
    id, fecha, placa, marca, tipo, modelo, cliente, telefono, conductor,
    kilometraje, trabajos_realizados, clave_control, observaciones,
    mano_obra, precio_repuestos, total
  ) values (
    v_format.folio,
    coalesce(v_format.fecha_salida, v_format.fecha_entrada),
    v_format.placa,
    v_format.marca,
    v_format.tipo_vehiculo,
    v_format.modelo,
    v_format.nombre_cliente,
    v_format.telefono_contacto,
    v_format.nombre_conductor,
    v_format.kilometraje::text,
    v_format.trabajos_realizados,
    v_format.clave_control,
    v_format.observaciones,
    v_format.labor_confirmed_amount,
    v_format.costo_repuestos,
    v_format.costo_total
  )
  on conflict (id) do update set
    fecha = excluded.fecha,
    placa = excluded.placa,
    marca = excluded.marca,
    tipo = excluded.tipo,
    modelo = excluded.modelo,
    cliente = excluded.cliente,
    telefono = excluded.telefono,
    conductor = excluded.conductor,
    kilometraje = excluded.kilometraje,
    trabajos_realizados = excluded.trabajos_realizados,
    clave_control = excluded.clave_control,
    observaciones = excluded.observaciones,
    mano_obra = excluded.mano_obra,
    precio_repuestos = excluded.precio_repuestos,
    total = excluded.total;

  return v_format;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_weekly_labor_goal(p_start_date date, p_end_date date)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select labor_goal
  from public.weekly_settlement_goals
  where period_start = p_start_date
    and period_end = p_end_date
  limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.set_weekly_labor_goal(p_start_date date, p_end_date date, p_goal numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_current_user_admin() then
    raise exception 'Solo un administrador puede establecer la meta semanal';
  end if;

  if p_end_date < p_start_date then
    raise exception 'El rango de la meta semanal no es válido';
  end if;

  if p_goal is null or p_goal <= 0 then
    raise exception 'La meta semanal debe ser mayor que cero';
  end if;

  if exists (
    select 1
    from public.weekly_settlements
    where start_date = p_start_date
      and end_date = p_end_date
      and deleted_at is null
  ) then
    raise exception 'La semana ya fue liquidada y su meta está cerrada';
  end if;

  insert into public.weekly_settlement_goals(
    period_start, period_end, labor_goal, created_by
  ) values (
    p_start_date, p_end_date, p_goal, auth.uid()
  )
  on conflict (period_start, period_end)
  do update set
    labor_goal = excluded.labor_goal,
    created_by = auth.uid(),
    updated_at = now();

  return p_goal;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.precio_sugerido_repuesto(p_id_identificacion text, p_marca text DEFAULT NULL::text, p_tipo_vehiculo text DEFAULT NULL::text)
 RETURNS TABLE(costo_sugerido numeric, precio_fecha timestamp with time zone, precio_match text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  SELECT sub.costo_unitario,
         sub.created_at,
         CASE sub.nivel WHEN 0 THEN 'vehiculo' WHEN 1 THEN 'marca' ELSE 'general' END
  FROM (
    SELECT r.costo_unitario, r.created_at,
           CASE
             WHEN p_marca IS NOT NULL AND f.marca IS NOT NULL
                  AND upper(btrim(f.marca)) = upper(btrim(p_marca))
                  AND p_tipo_vehiculo IS NOT NULL AND f.tipo_vehiculo IS NOT NULL
                  AND upper(btrim(f.tipo_vehiculo)) = upper(btrim(p_tipo_vehiculo))
               THEN 0
             WHEN p_marca IS NOT NULL AND f.marca IS NOT NULL
                  AND upper(btrim(f.marca)) = upper(btrim(p_marca))
               THEN 1
             ELSE 2
           END AS nivel
    FROM public.repuestos r
    LEFT JOIN public.formatos f ON f.folio = r.id_repuesto
    WHERE r.deleted_at IS NULL
      AND r.costo_unitario > 0
      AND r.id_identificacion = p_id_identificacion
  ) sub
  ORDER BY sub.nivel, sub.created_at DESC
  LIMIT 1
$function$
;

CREATE OR REPLACE FUNCTION public.buscar_catalogo_repuestos(p_query text, p_marca text DEFAULT NULL::text, p_tipo_vehiculo text DEFAULT NULL::text, p_limit integer DEFAULT 30)
 RETURNS TABLE(id uuid, id_identificacion text, descripcion text, created_at timestamp with time zone, costo_sugerido numeric, precio_fecha timestamp with time zone, precio_match text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  WITH candidatos AS (
    SELECT c.id, c.id_identificacion, c.descripcion, c.created_at,
           COALESCE(c.descripcion ILIKE btrim(p_query) || '%', false) AS empieza_con
    FROM public.catalogo_repuestos c
    WHERE c.deleted_at IS NULL
      AND (p_query IS NULL OR btrim(p_query) = ''
           OR c.descripcion ILIKE '%' || btrim(p_query) || '%')
    ORDER BY empieza_con DESC, c.descripcion
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 30), 1), 100)
  )
  SELECT cand.id, cand.id_identificacion, cand.descripcion, cand.created_at,
         p.costo_sugerido, p.precio_fecha, p.precio_match
  FROM candidatos cand
  LEFT JOIN LATERAL public.precio_sugerido_repuesto(
    cand.id_identificacion, p_marca, p_tipo_vehiculo
  ) p ON true
  ORDER BY cand.empieza_con DESC, cand.descripcion
$function$
;

CREATE OR REPLACE FUNCTION public.get_weekly_performance()
 RETURNS TABLE(active_count bigint, ready_count bigint, finalized_count bigint, current_confirmed_labor numeric, current_confirmed_count integer, previous_confirmed_labor numeric, previous_confirmed_count integer, percentage_change numeric, has_comparison boolean, baseline_end_date date, cycle_start_date date, cycle_end_date date, cycle_settled boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_cycle_start date := date_trunc('week', current_date)::date;
  v_cycle_end date := date_trunc('week', current_date)::date + 5;
  v_next_cycle date := date_trunc('week', current_date)::date + 7;
begin
  return query
  with estados as (
    select
      count(*) filter (where estado = 'ACTIVO') as active_count,
      count(*) filter (where estado = 'LISTO') as ready_count,
      count(*) filter (where estado = 'FINALIZADO') as finalized_count
    from public.formatos
    where deleted_at is null
  ),
  ciclo as (
    -- Incluye FINALIZADO: liquidar ya no borra el avance de la semana.
    select
      coalesce(
        sum(coalesce(f.labor_confirmed_amount, f.costo_mano_obra, 0)),
        0
      ) as confirmed_labor,
      count(*)::integer as confirmed_count
    from public.formatos f
    where f.deleted_at is null
      and f.estado in ('LISTO', 'FINALIZADO')
      and coalesce(f.labor_confirmed_amount, f.costo_mano_obra, 0) > 0
      and coalesce(f.fecha_salida, f.labor_confirmed_at::date) >= v_cycle_start
      and coalesce(f.fecha_salida, f.labor_confirmed_at::date) < v_next_cycle
  ),
  anterior as (
    -- Solo ciclos anteriores: la liquidación de esta semana no se compara
    -- contra sí misma.
    select
      confirmed_labor_total,
      confirmed_format_count,
      end_date
    from public.weekly_settlements
    where deleted_at is null
      and end_date < v_cycle_start
    order by end_date desc, created_at desc
    limit 1
  ),
  cerrada as (
    select exists (
      select 1
      from public.weekly_settlements
      where deleted_at is null
        and end_date >= v_cycle_start
        and start_date <= v_cycle_end
    ) as cycle_settled
  )
  select
    e.active_count,
    e.ready_count,
    e.finalized_count,
    c.confirmed_labor,
    c.confirmed_count,
    coalesce(p.confirmed_labor_total, 0),
    coalesce(p.confirmed_format_count, 0),
    case
      when p.end_date is null or coalesce(p.confirmed_labor_total, 0) <= 0
        then null
      else round(
        ((c.confirmed_labor - p.confirmed_labor_total)
          / p.confirmed_labor_total) * 100,
        2
      )
    end,
    p.end_date is not null and coalesce(p.confirmed_labor_total, 0) > 0,
    p.end_date,
    v_cycle_start,
    v_cycle_end,
    s.cycle_settled
  from estados e
  cross join ciclo c
  cross join cerrada s
  left join anterior p on true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_weekly_settlement(p_settlement_id uuid, p_hard boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_settlement public.weekly_settlements;
  v_format_ids uuid[];
  v_format_id uuid;
  v_reason text;
  v_voided integer := 0;
  v_reopened integer := 0;
begin
  if not public.is_current_user_admin() then
    raise exception 'Solo un administrador puede eliminar liquidaciones';
  end if;

  select * into v_settlement
  from public.weekly_settlements
  where id = p_settlement_id
  for update;

  if not found then
    raise exception 'Liquidación no encontrada';
  end if;

  v_reason := format(
    'Liquidación eliminada (%s a %s)',
    to_char(v_settlement.start_date, 'DD/MM/YYYY'),
    to_char(v_settlement.end_date, 'DD/MM/YYYY')
  );

  select array_agg(distinct si.format_id)
  into v_format_ids
  from public.settlement_items si
  join public.formatos f on f.id = si.format_id
  where si.settlement_id = p_settlement_id
    and coalesce(si.is_advance, false) = false
    and f.estado = 'FINALIZADO'
    and f.deleted_at is null;

  insert into public.settlement_deferrals_voided(
    id, settlement_id, format_id, period_start, period_end, reason,
    created_by, created_at, resolved_at, voided_by
  )
  select
    d.id, p_settlement_id, d.format_id, d.period_start, d.period_end, d.reason,
    d.created_by, d.created_at, d.resolved_at, auth.uid()
  from public.settlement_deferrals d
  where d.resolved_settlement_id = p_settlement_id
  on conflict (id) do update set
    settlement_id = excluded.settlement_id,
    format_id = excluded.format_id,
    period_start = excluded.period_start,
    period_end = excluded.period_end,
    reason = excluded.reason,
    created_by = excluded.created_by,
    created_at = excluded.created_at,
    resolved_at = excluded.resolved_at,
    voided_at = now(),
    voided_by = excluded.voided_by;

  update public.settlement_deferrals
  set
    resolved_at = null,
    resolved_settlement_id = null
  where resolved_settlement_id = p_settlement_id;

  with movidos as (
    delete from public.settlement_items
    where settlement_id = p_settlement_id
    returning *
  )
  insert into public.settlement_items_voided(
    id,
    settlement_id,
    format_id,
    original_amount,
    adjusted_amount,
    previous_advances,
    is_advance,
    notes,
    created_at,
    period_start,
    period_end,
    voided_by,
    format_previous_state,
    format_fecha_salida,
    format_labor_confirmed_amount,
    format_labor_confirmed_at,
    format_labor_confirmed_by
  )
  select
    m.id,
    m.settlement_id,
    m.format_id,
    m.original_amount,
    m.adjusted_amount,
    m.previous_advances,
    m.is_advance,
    m.notes,
    m.created_at,
    v_settlement.start_date,
    v_settlement.end_date,
    auth.uid(),
    f.estado,
    f.fecha_salida,
    f.labor_confirmed_amount,
    f.labor_confirmed_at,
    f.labor_confirmed_by
  from movidos m
  left join public.formatos f on f.id = m.format_id
  on conflict (id) do nothing;
  get diagnostics v_voided = row_count;

  -- Los formatos vuelven al taller conservando su fecha de salida: borrar el
  -- cierre corrige la contabilidad, no reabre el trabajo.
  foreach v_format_id in array coalesce(v_format_ids, array[]::uuid[])
  loop
    if public.send_format_back_to_workshop(v_format_id, v_reason, true) then
      v_reopened := v_reopened + 1;
    end if;
  end loop;

  if coalesce(p_hard, false) then
    delete from public.weekly_settlements where id = p_settlement_id;
  else
    update public.weekly_settlements
    set
      deleted_at = now(),
      deleted_by = auth.uid()
    where id = p_settlement_id;
  end if;

  return jsonb_build_object(
    'id', p_settlement_id,
    'hard_deleted', coalesce(p_hard, false),
    'voided_items', v_voided,
    'reopened_formats', v_reopened
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.precio_sugerido_servicio(p_servicio text, p_marca text DEFAULT NULL::text, p_tipo_vehiculo text DEFAULT NULL::text)
 RETURNS TABLE(precio_sugerido numeric, precio_fecha timestamp with time zone, precio_match text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select sub.precio_mano_obra,
         sub.created_at,
         case sub.nivel when 0 then 'vehiculo' when 1 then 'marca' else 'general' end
  from (
    select s.precio_mano_obra,
           s.created_at,
           case
             when p_marca is not null and f.marca is not null
                  and upper(btrim(f.marca)) = upper(btrim(p_marca))
                  and p_tipo_vehiculo is not null and f.tipo_vehiculo is not null
                  and upper(btrim(f.tipo_vehiculo)) = upper(btrim(p_tipo_vehiculo))
               then 0
             when p_marca is not null and f.marca is not null
                  and upper(btrim(f.marca)) = upper(btrim(p_marca))
               then 1
             else 2
           end as nivel
    from public.servicios s
    left join public.formatos f on f.folio = s.formato_folio
    where s.deleted_at is null
      and s.precio_mano_obra > 0
      and public.normalize_service_name(s.servicio) =
          public.normalize_service_name(p_servicio)
  ) sub
  order by sub.nivel, sub.created_at desc
  limit 1
$function$
;

CREATE OR REPLACE FUNCTION public.buscar_servicios_frecuentes(p_marca text DEFAULT NULL::text, p_tipo_vehiculo text DEFAULT NULL::text, p_limit integer DEFAULT 15)
 RETURNS TABLE(servicio text, usos bigint, precio_sugerido numeric, precio_fecha timestamp with time zone, precio_match text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with normalizados as (
    select public.normalize_service_name(s.servicio) as clave,
           btrim(s.servicio) as etiqueta
    from public.servicios s
    where s.deleted_at is null
      and public.normalize_service_name(s.servicio) <> ''
  ),
  conteo as (
    select clave, count(*) as usos
    from normalizados
    group by clave
  ),
  etiqueta_top as (
    select distinct on (clave) clave, etiqueta
    from (
      select clave, etiqueta, count(*) as veces
      from normalizados
      group by clave, etiqueta
    ) e
    order by clave, veces desc, etiqueta
  )
  select t.etiqueta, c.usos, p.precio_sugerido, p.precio_fecha, p.precio_match
  from conteo c
  join etiqueta_top t on t.clave = c.clave
  left join lateral public.precio_sugerido_servicio(
    t.etiqueta, p_marca, p_tipo_vehiculo
  ) p on true
  order by c.usos desc, t.etiqueta
  limit least(greatest(coalesce(p_limit, 15), 1), 100)
$function$
;

CREATE OR REPLACE FUNCTION public.add_servicio_if_absent(p_formato_folio text, p_servicio text, p_created_at timestamp with time zone DEFAULT now(), p_precio_mano_obra numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_service public.servicios;
  v_name text;
  v_precio numeric;
begin
  if auth.uid() is null then
    raise exception 'Usuario no autenticado' using errcode = '42501';
  end if;

  v_name := trim(coalesce(p_servicio, ''));
  if public.normalize_service_name(v_name) = '' then
    raise exception 'El nombre del servicio es requerido' using errcode = '22023';
  end if;

  v_precio := nullif(greatest(coalesce(p_precio_mano_obra, 0), 0), 0);

  insert into public.servicios (
    formato_folio, servicio, created_at, precio_mano_obra
  )
  values (
    trim(p_formato_folio), v_name, coalesce(p_created_at, now()), v_precio
  )
  on conflict (
    formato_folio,
    public.normalize_service_name(servicio)
  ) where deleted_at is null
  do nothing
  returning * into v_service;

  if v_service.id is null then
    select *
    into v_service
    from public.servicios
    where formato_folio = trim(p_formato_folio)
      and public.normalize_service_name(servicio) =
          public.normalize_service_name(v_name)
      and deleted_at is null
    order by created_at, id
    limit 1;
  end if;

  return to_jsonb(v_service);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_servicio_precio(p_servicio_id uuid, p_precio numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_service public.servicios;
begin
  if auth.uid() is null then
    raise exception 'Usuario no autenticado' using errcode = '42501';
  end if;

  if p_precio is not null and p_precio < 0 then
    raise exception 'El precio no puede ser negativo' using errcode = '22023';
  end if;

  update public.servicios
  set precio_mano_obra = nullif(coalesce(p_precio, 0), 0)
  where id = p_servicio_id
    and deleted_at is null
  returning * into v_service;

  if v_service.id is null then
    raise exception 'El servicio no existe o ya fue eliminado'
      using errcode = 'P0002';
  end if;

  return to_jsonb(v_service);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_ready_labor_confirmation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.estado = 'LISTO'
     and new.estado = 'LISTO'
     and new.costo_mano_obra is distinct from old.costo_mano_obra
     and new.labor_confirmed_amount is not distinct from old.labor_confirmed_amount then
    if coalesce(new.costo_mano_obra, 0) < 0
       or (
         coalesce(new.costo_mano_obra, 0) = 0
         and upper(trim(coalesce(new.tipo_formato, ''))) <> 'GARANTIA'
       ) then
      raise exception 'La mano de obra de un formato LISTO debe ser mayor que cero';
    end if;

    new.labor_confirmed_amount := coalesce(new.costo_mano_obra, 0);
    new.labor_confirmed_at := now();
    new.labor_confirmed_by := coalesce(auth.uid(), old.labor_confirmed_by);
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_variacion_on_parts_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.estado in ('LISTO', 'FINALIZADO')
     and new.costo_repuestos is distinct from old.costo_repuestos then
    update public.reportes_variacion
    set total = coalesce(new.labor_confirmed_amount, new.costo_mano_obra, 0)
      + coalesce(new.costo_repuestos, 0)
    where id_formato = new.id;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.current_test_environment_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select mode.environment_id
  from public.format_development_modes mode
  where mode.user_id = (select auth.uid())
    and mode.is_enabled
  limit 1
$function$
;

CREATE OR REPLACE FUNCTION public.recalculate_settlement_totals(p_settlement_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_settlement public.weekly_settlements;
  v_gross numeric := 0;
  v_liquidated numeric := 0;
  v_confirmed numeric := 0;
  v_count integer := 0;
  v_fund_gross numeric;
begin
  select * into v_settlement
  from public.weekly_settlements
  where id = p_settlement_id;

  if not found then
    return;
  end if;

  select
    coalesce(sum(si.original_amount), 0),
    coalesce(sum(si.adjusted_amount), 0),
    coalesce(sum(si.original_amount) filter (
      where coalesce(si.is_advance, false) = false
    ), 0),
    count(*) filter (where coalesce(si.is_advance, false) = false)
  into v_gross, v_liquidated, v_confirmed, v_count
  from public.settlement_items si
  where si.settlement_id = p_settlement_id;

  v_fund_gross := v_liquidated * (coalesce(v_settlement.wage_fund_percentage, 0) / 100);

  update public.weekly_settlements
  set
    total_labor_gross = v_gross,
    total_labor_liquidated = v_liquidated,
    confirmed_labor_total = v_confirmed,
    confirmed_format_count = v_count,
    wage_fund_total = greatest(
      v_fund_gross - coalesce(v_settlement.total_referral_commission, 0),
      0
    ),
    shop_profit = v_liquidated - v_fund_gross,
    weekly_labor_actual = v_confirmed
  where id = p_settlement_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.test_environment_row_visible(p_environment_id uuid, p_include_production_baseline boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case
    when public.current_test_environment_id() is null
      then p_environment_id is null
    when p_include_production_baseline
      then p_environment_id is null
        or p_environment_id = public.current_test_environment_id()
    else p_environment_id = public.current_test_environment_id()
  end
$function$
;

CREATE OR REPLACE FUNCTION public.test_environment_row_writable(p_environment_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select p_environment_id is not distinct from
    public.current_test_environment_id()
$function$
;

CREATE OR REPLACE FUNCTION public.sync_reporte_variacion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.deleted_at is not null
     or new.estado not in ('LISTO', 'FINALIZADO') then
    delete from public.reportes_variacion where id_formato = new.id;
    return new;
  end if;

  insert into public.reportes_variacion(fecha, mano_obra, total, id_formato)
  values (
    coalesce(new.fecha_salida, new.fecha_entrada, current_date),
    coalesce(new.labor_confirmed_amount, new.costo_mano_obra, 0),
    coalesce(new.labor_confirmed_amount, new.costo_mano_obra, 0)
      + coalesce(new.costo_repuestos, 0),
    new.id
  )
  on conflict (id_formato) where id_formato is not null
  do update set
    fecha = excluded.fecha,
    mano_obra = excluded.mano_obra,
    total = excluded.total;

  return new;
exception when others then
  raise warning 'No pude sincronizar la variación del formato %: %',
    new.folio, sqlerrm;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.resync_reportes_variacion()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_realineadas integer := 0;
  v_borradas integer := 0;
begin
  if not public.is_current_user_admin() then
    raise exception
      'Solo un administrador puede resincronizar el informe de variación';
  end if;

  update public.reportes_variacion rv
  set
    fecha = coalesce(f.fecha_salida, f.fecha_entrada, rv.fecha),
    mano_obra = coalesce(f.labor_confirmed_amount, f.costo_mano_obra, 0),
    total = coalesce(f.labor_confirmed_amount, f.costo_mano_obra, 0)
      + coalesce(f.costo_repuestos, 0)
  from public.formatos f
  where f.id = rv.id_formato
    and f.deleted_at is null
    and f.estado in ('LISTO', 'FINALIZADO')
    and (
      rv.fecha is distinct from coalesce(f.fecha_salida, f.fecha_entrada, rv.fecha)
      or rv.mano_obra is distinct from
        coalesce(f.labor_confirmed_amount, f.costo_mano_obra, 0)
      or rv.total is distinct from
        coalesce(f.labor_confirmed_amount, f.costo_mano_obra, 0)
          + coalesce(f.costo_repuestos, 0)
    );
  get diagnostics v_realineadas = row_count;

  delete from public.reportes_variacion rv
  using public.formatos f
  where f.id = rv.id_formato
    and (f.deleted_at is not null or f.estado not in ('LISTO', 'FINALIZADO'));
  get diagnostics v_borradas = row_count;

  return v_realineadas + v_borradas;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.guard_global_test_environment_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_active uuid := public.current_test_environment_id();
  v_cleanup uuid := nullif(
    current_setting('app.global_test_cleanup_id', true),
    ''
  )::uuid;
begin
  if tg_op = 'INSERT' then
    new.test_environment_id := v_active;
    if tg_table_name = 'formatos' then
      new.is_development := v_active is not null;
      new.created_by := coalesce(new.created_by, auth.uid());
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if v_cleanup is not null
       and old.test_environment_id = v_cleanup then
      return old;
    end if;
    if old.test_environment_id is distinct from v_active then
      raise exception
        'No puedes borrar datos de otro entorno desde el entorno actual'
        using errcode = '42501';
    end if;
    return old;
  end if;

  if old.test_environment_id is distinct from v_active then
    raise exception
      'No puedes modificar datos de producción o de otro entorno durante una prueba'
      using errcode = '42501';
  end if;
  new.test_environment_id := old.test_environment_id;
  if tg_table_name = 'formatos' then
    new.is_development := old.test_environment_id is not null;
    new.created_by := coalesce(new.created_by, old.created_by, auth.uid());
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ensure_global_test_environment_mode()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_environment_id uuid;
begin
  if nullif(
    current_setting('app.global_test_cleanup_id', true),
    ''
  ) is not null then
    return new;
  end if;
  if not new.is_enabled or new.environment_id is not null then
    return new;
  end if;

  insert into public.global_test_environments(
    owner_id,
    scope_key,
    last_activated_at
  ) values (
    new.user_id,
    'shared',
    now()
  )
  on conflict (scope_key) do update
    set last_activated_at = excluded.last_activated_at
  returning id into v_environment_id;

  new.environment_id := v_environment_id;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.guard_format_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enabled boolean;
  v_action text := coalesce(current_setting('app.format_workflow_action', true), '');
  v_economic_change boolean;
  v_settled boolean;
begin
  select coalesce(value, false)
  into v_enabled
  from public.app_settings
  where key = 'ready_settlement_workflow_enabled';

  if not coalesce(v_enabled, false) then
    return new;
  end if;

  if old.estado = 'FINALIZADO' and new.estado <> 'FINALIZADO'
     and not (new.estado = 'ACTIVO' and v_action = 'reopen_finalized') then
    raise exception 'Use reopen_finalized_format para devolver el formato al taller';
  end if;

  if old.estado = 'ACTIVO' and new.estado <> 'ACTIVO'
     and not (new.estado = 'LISTO' and v_action = 'mark_ready')
     and not (new.estado = 'FINALIZADO' and v_action = 'restore_settlement') then
    raise exception 'Use mark_format_ready para cambiar un formato ACTIVO';
  end if;

  if old.estado = 'LISTO' then
    if new.estado = 'ACTIVO' and v_action <> 'reopen_ready' then
      raise exception 'Use reopen_ready_format para reabrir un formato LISTO';
    end if;
    if new.estado = 'FINALIZADO'
       and v_action not in (
         'close_settlement', 'restore_settlement', 'finalize_due'
       ) then
      raise exception 'Un formato LISTO solo se finaliza al cerrar su semana';
    end if;

    v_economic_change := new.estado = 'LISTO' and (
      new.costo_mano_obra is distinct from old.costo_mano_obra
      or new.costo_repuestos is distinct from old.costo_repuestos
      or new.costo_total is distinct from old.costo_total
      or new.trabajos_realizados is distinct from old.trabajos_realizados
      or new.fecha_salida is distinct from old.fecha_salida
      or new.labor_confirmed_amount is distinct from old.labor_confirmed_amount
      or new.labor_confirmed_at is distinct from old.labor_confirmed_at
      or new.labor_confirmed_by is distinct from old.labor_confirmed_by
    );

    if v_economic_change and v_action <> 'restore_settlement' then
      if not public.is_current_user_admin() then
        raise exception
          'El contenido económico de un formato LISTO solo lo puede ajustar un administrador';
      end if;

      if exists (
        select 1
        from public.settlement_items si
        join public.weekly_settlements ws on ws.id = si.settlement_id
        where si.format_id = new.id
          and coalesce(si.is_advance, false) = false
          and ws.deleted_at is null
      ) then
        raise exception
          'El formato ya fue liquidado: devuélvelo al taller antes de editarlo';
      end if;
    end if;
  end if;

  if old.estado = 'FINALIZADO' and new.estado = 'FINALIZADO'
     and v_action <> 'restore_settlement' then
    v_economic_change :=
      new.costo_mano_obra is distinct from old.costo_mano_obra
      or new.labor_confirmed_amount is distinct from old.labor_confirmed_amount;

    if v_economic_change or new.fecha_salida is distinct from old.fecha_salida then
      if not public.is_current_user_admin() then
        raise exception
          'Un formato FINALIZADO solo lo puede corregir un administrador';
      end if;
    end if;

    if v_economic_change then
      select exists (
        select 1
        from public.settlement_items si
        join public.weekly_settlements ws on ws.id = si.settlement_id
        where si.format_id = new.id
          and coalesce(si.is_advance, false) = false
          and ws.deleted_at is null
      ) into v_settled;

      if v_settled then
        raise exception
          'La mano de obra de un formato liquidado no se puede cambiar: elimina la liquidación de esa semana primero';
      end if;
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.list_global_test_environment_files()
 RETURNS text[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with candidates(url) as (
    select formato.url_documento
    from public.formatos formato
    where formato.test_environment_id = public.current_test_environment_id()
    union all
    select value #>> '{}'
    from public.formatos formato
    cross join lateral jsonb_path_query(
      coalesce(formato.fotos_vehiculo, '{}'::jsonb),
      '$.** ? (@.type() == "string")'
    ) value
    where formato.test_environment_id = public.current_test_environment_id()
    union all
    select factura.factura_pdf
    from public.facturas factura
    where factura.test_environment_id = public.current_test_environment_id()
    union all
    select electronica.pdf_url
    from public.facturas_electronicas electronica
    where electronica.test_environment_id = public.current_test_environment_id()
    union all
    select electronica.xml_url
    from public.facturas_electronicas electronica
    where electronica.test_environment_id = public.current_test_environment_id()
    union all
    select electronica.qr_url
    from public.facturas_electronicas electronica
    where electronica.test_environment_id = public.current_test_environment_id()
    union all
    select proveedor.url_imagen
    from public.facturas_proveedores proveedor
    where proveedor.test_environment_id = public.current_test_environment_id()
    union all
    select photo.photo_url
    from public.trashed_photos photo
    where photo.test_environment_id = public.current_test_environment_id()
  )
  select coalesce(array_agg(distinct url), array[]::text[])
  from candidates
  where nullif(trim(url), '') is not null
    and url like '%/api/drive/files/%'
$function$
;

CREATE OR REPLACE FUNCTION public.apply_offline_mutation(p_operation_id uuid, p_kind text, p_entity_key text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private'
AS $function$
declare
  v_active uuid := public.current_test_environment_id();
  v_declared uuid := nullif(
    trim(coalesce(p_payload ->> '_test_environment_id', '')),
    ''
  )::uuid;
begin
  if auth.uid() is null then
    raise exception 'Usuario no autenticado' using errcode = '42501';
  end if;

  if v_declared is distinct from v_active then
    return jsonb_build_object(
      'status', 'conflict',
      'message',
        'Este cambio pertenece a otro entorno. Activa el entorno correcto antes de sincronizarlo.'
    );
  end if;

  if v_active is not null
     and lower(trim(coalesce(p_kind, ''))) in (
       'profile.update',
       'setting.set',
       'weekly_goal.set',
       'weekly_goal.clear'
     ) then
    return jsonb_build_object(
      'status', 'conflict',
      'message',
        'La configuración real y los perfiles están bloqueados en el entorno global de pruebas.'
    );
  end if;

  return private.apply_offline_mutation(
    p_operation_id,
    p_kind,
    p_entity_key,
    p_payload - '_test_environment_id'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_test_vehicle_registry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.test_environment_id is null
     or nullif(trim(new.placa), '') is null then
    return new;
  end if;

  if not exists (
    select 1
    from public.vehiculos_registrados vehicle
    where upper(trim(vehicle.placa)) = upper(trim(new.placa))
      and vehicle.test_environment_id is not distinct from
        new.test_environment_id
  ) and not exists (
    select 1
    from public.vehiculos_registrados vehicle
    where upper(trim(vehicle.placa)) = upper(trim(new.placa))
      and vehicle.test_environment_id is null
  ) then
    insert into public.vehiculos_registrados(
      placa,
      marca,
      tipo_vehiculo
    ) values (
      upper(trim(new.placa)),
      new.marca,
      new.tipo_vehiculo
    );
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_formato_global()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.folio is null then
    return new;
  end if;

  if new.deleted_at is not null
     or new.estado not in ('LISTO', 'FINALIZADO') then
    delete from public.formatos_globales where id = new.folio;
    return new;
  end if;

  insert into public.formatos_globales(
    id, fecha, placa, marca, tipo, modelo, cliente, telefono, conductor,
    kilometraje, trabajos_realizados, clave_control, observaciones,
    mano_obra, precio_repuestos, total
  ) values (
    new.folio,
    coalesce(new.fecha_salida, new.fecha_entrada),
    new.placa,
    new.marca,
    new.tipo_vehiculo,
    new.modelo,
    new.nombre_cliente,
    new.telefono_contacto,
    new.nombre_conductor,
    new.kilometraje::text,
    new.trabajos_realizados,
    new.clave_control,
    new.observaciones,
    coalesce(new.labor_confirmed_amount, new.costo_mano_obra),
    new.costo_repuestos,
    new.costo_total
  )
  on conflict (id) do update set
    fecha = excluded.fecha,
    placa = excluded.placa,
    marca = excluded.marca,
    tipo = excluded.tipo,
    modelo = excluded.modelo,
    cliente = excluded.cliente,
    telefono = excluded.telefono,
    conductor = excluded.conductor,
    kilometraje = excluded.kilometraje,
    trabajos_realizados = excluded.trabajos_realizados,
    clave_control = excluded.clave_control,
    observaciones = excluded.observaciones,
    mano_obra = excluded.mano_obra,
    precio_repuestos = excluded.precio_repuestos,
    total = excluded.total;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_repuesto_profit_prices()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_current public.repuestos;
begin
  if tg_op = 'UPDATE'
     and new.precio_neto_unitario is not distinct from old.precio_neto_unitario
     and new.costo_unitario is not distinct from old.costo_unitario
     and new.traido_por is not distinct from old.traido_por then
    return null;
  end if;

  select * into v_current from public.repuestos where id = new.id;
  if not found then return null; end if;

  if upper(trim(coalesce(v_current.traido_por, ''))) = 'TALLER' then
    if v_current.costo_unitario <= 0
       or v_current.costo_unitario <> trunc(v_current.costo_unitario)
       or (
         v_current.precio_neto_unitario is not null
         and (
           v_current.precio_neto_unitario <= 0
           or v_current.costo_unitario < v_current.precio_neto_unitario
           or v_current.precio_neto_unitario <> trunc(v_current.precio_neto_unitario)
         )
       ) then
      raise exception
        'Los precios registrados del repuesto deben ser enteros, positivos y coherentes'
        using errcode = '22023';
    end if;
  elsif v_current.precio_neto_unitario is not null then
    raise exception 'Un repuesto del cliente no puede registrar precio neto'
      using errcode = '22023';
  end if;
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.save_repuesto_with_catalog_profit_atomic(p_item jsonb, p_catalog_description text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_catalog jsonb;
  v_saved jsonb;
begin
  v_catalog := public.create_catalogo_repuesto_atomic(p_catalog_description);
  v_saved := public.save_repuestos_profit_atomic(
    jsonb_build_array(
      p_item || jsonb_build_object(
        'id_identificacion', v_catalog->>'id_identificacion',
        'descripcion', v_catalog->>'descripcion'
      )
    )
  );
  return v_saved->0;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_repuesto_with_catalog_profit_atomic(p_id uuid, p_data jsonb, p_catalog_description text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_catalog jsonb;
begin
  v_catalog := public.create_catalogo_repuesto_atomic(p_catalog_description);
  return public.update_repuesto_profit_atomic(
    p_id,
    p_data || jsonb_build_object(
      'id_identificacion', v_catalog->>'id_identificacion',
      'descripcion', v_catalog->>'descripcion'
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_repuesto_profit_atomic(p_id uuid, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_quantity integer;
  v_description text;
  v_origin text;
  v_net numeric;
  v_final numeric;
  v_updated public.repuestos;
begin
  if auth.uid() is null then
    raise exception 'Usuario no autenticado' using errcode = '42501';
  end if;
  if jsonb_typeof(p_data) <> 'object' then
    raise exception 'Los datos del repuesto no tienen un formato valido'
      using errcode = '22023';
  end if;

  v_quantity := nullif(p_data ->> 'cantidad', '')::integer;
  v_description := regexp_replace(
    trim(coalesce(p_data ->> 'descripcion', '')), '\s+', ' ', 'g'
  );
  v_origin := upper(trim(coalesce(p_data ->> 'traido_por', '')));
  v_net := nullif(p_data ->> 'precio_neto_unitario', '')::numeric;
  v_final := nullif(p_data ->> 'costo_unitario', '')::numeric;

  if v_quantity is null
     or v_quantity <= 0
     or v_quantity > 100000
     or v_description = ''
     or v_origin not in ('TALLER', 'CLIENTE')
     or v_final is null
     or v_final <= 0
     or abs(v_final) > 1000000000000 then
    raise exception 'Los datos del repuesto no son validos'
      using errcode = '22023';
  end if;

  if v_origin = 'TALLER'
     and (
       v_final <> trunc(v_final)
       or (
         v_net is not null
         and (
           v_net <= 0
           or v_final < v_net
           or v_net <> trunc(v_net)
         )
       )
     ) then
    raise exception
      'Revisa el precio final y el precio neto ingresado'
      using errcode = '22023';
  end if;

  update public.repuestos
  set
    id_identificacion = nullif(trim(p_data ->> 'id_identificacion'), ''),
    descripcion = v_description,
    cantidad = v_quantity,
    precio_neto_unitario = case when v_origin = 'TALLER' then v_net else null end,
    costo_unitario = v_final,
    costo_total_linea = v_quantity * v_final,
    traido_por = v_origin
  where id = p_id
    and deleted_at is null
  returning * into v_updated;

  if v_updated.id is null then
    raise exception 'El repuesto no existe o fue eliminado'
      using errcode = 'P0002';
  end if;
  return to_jsonb(v_updated);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.save_repuestos_profit_atomic(p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_saved jsonb;
  v_result jsonb;
begin
  if jsonb_typeof(p_items) <> 'array' then
    raise exception 'Los repuestos deben enviarse como una lista';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_items) as item(
      traido_por text,
      precio_neto_unitario numeric,
      costo_unitario numeric
    )
    where upper(trim(coalesce(item.traido_por, ''))) = 'TALLER'
      and (
        item.costo_unitario is null
        or item.costo_unitario <= 0
        or item.costo_unitario <> trunc(item.costo_unitario)
        or (
          item.precio_neto_unitario is not null
          and (
            item.precio_neto_unitario <= 0
            or item.costo_unitario < item.precio_neto_unitario
            or item.precio_neto_unitario <> trunc(item.precio_neto_unitario)
          )
        )
      )
  ) then
    raise exception
      'Revisa el precio final y los precios netos que hayas ingresado'
      using errcode = '22023';
  end if;

  v_saved := public.save_repuestos_atomic(p_items);

  update public.repuestos as repuesto
  set precio_neto_unitario = case
    when upper(trim(coalesce(item.traido_por, ''))) = 'TALLER'
      then item.precio_neto_unitario
    else null
  end
  from jsonb_to_recordset(p_items) as item(
    id uuid,
    traido_por text,
    precio_neto_unitario numeric
  )
  where repuesto.id = item.id;

  select coalesce(jsonb_agg(to_jsonb(repuesto) order by repuesto.created_at), '[]')
  into v_result
  from public.repuestos as repuesto
  where repuesto.id in (
    select item.id from jsonb_to_recordset(p_items) as item(id uuid)
  );

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.close_weekly_settlement_with_parts(p_start_date date, p_end_date date, p_wage_fund_percentage numeric, p_items jsonb, p_workers jsonb, p_total_bonus numeric DEFAULT 0, p_deferrals jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_active_environment uuid := public.current_test_environment_id();
  v_result jsonb;
  v_settlement_id uuid;
  v_item jsonb;
  v_part public.repuestos;
  v_format public.formatos;
  v_base_percentage numeric;
  v_percentage numeric;
  v_profit numeric;
  v_commission numeric;
  v_worker_name text;
  v_parts_profit_total numeric;
  v_parts_commission_total numeric;
begin
  if not public.is_current_user_admin() then
    raise exception 'Solo un administrador puede cerrar liquidaciones';
  end if;

  for v_item in
    select value from jsonb_array_elements(coalesce(p_items, '[]'::jsonb))
  loop
    if coalesce((v_item->>'is_advance')::boolean, false) then
      continue;
    end if;

    select * into v_format
    from public.formatos
    where id = (v_item->>'format_id')::uuid
      and deleted_at is null
      and test_environment_id is not distinct from v_active_environment
    for update;
    if not found then
      raise exception 'Uno de los formatos seleccionados no pertenece al entorno actual';
    end if;

    if exists (
      select legacy.repuesto_id
      from jsonb_to_recordset(
        coalesce(v_item->'legacy_net_prices', '[]'::jsonb)
      ) as legacy(repuesto_id uuid, net_unit_price numeric)
      group by legacy.repuesto_id
      having count(*) > 1
    ) then
      raise exception 'Un repuesto no puede tener dos precios netos en el cierre';
    end if;

    if exists (
      select 1
      from jsonb_to_recordset(
        coalesce(v_item->'legacy_net_prices', '[]'::jsonb)
      ) as legacy(repuesto_id uuid, net_unit_price numeric)
      left join public.repuestos as repuesto
        on repuesto.id = legacy.repuesto_id
       and repuesto.id_repuesto = v_format.folio
       and repuesto.test_environment_id is not distinct from v_active_environment
       and repuesto.deleted_at is null
       and upper(trim(coalesce(repuesto.traido_por, ''))) = 'TALLER'
      where repuesto.id is null
         or legacy.net_unit_price is null
         or legacy.net_unit_price <= 0
         or legacy.net_unit_price <> trunc(legacy.net_unit_price)
         or legacy.net_unit_price > repuesto.costo_unitario
    ) then
      raise exception 'Un precio neto historico no es valido para el formato';
    end if;

    update public.repuestos as repuesto
    set precio_neto_unitario = legacy.net_unit_price
    from jsonb_to_recordset(
      coalesce(v_item->'legacy_net_prices', '[]'::jsonb)
    ) as legacy(repuesto_id uuid, net_unit_price numeric)
    where repuesto.id = legacy.repuesto_id
      and repuesto.id_repuesto = v_format.folio
      and repuesto.test_environment_id is not distinct from v_active_environment
      and repuesto.deleted_at is null
      and upper(trim(coalesce(repuesto.traido_por, ''))) = 'TALLER';

    if nullif(trim(coalesce(v_format.referido_por, '')), '') is not null
       and exists (
         select 1
         from public.repuestos as repuesto
         where repuesto.id_repuesto = v_format.folio
           and repuesto.test_environment_id is not distinct from v_active_environment
           and repuesto.deleted_at is null
           and upper(trim(coalesce(repuesto.traido_por, ''))) = 'TALLER'
           and (
             repuesto.precio_neto_unitario is null
             or repuesto.precio_neto_unitario <= 0
             or repuesto.costo_unitario <= 0
             or repuesto.costo_unitario < repuesto.precio_neto_unitario
             or repuesto.precio_neto_unitario <> trunc(repuesto.precio_neto_unitario)
             or repuesto.costo_unitario <> trunc(repuesto.costo_unitario)
           )
       ) then
      raise exception
        'Todos los repuestos del taller del formato % necesitan un precio neto valido',
        v_format.folio;
    end if;

    v_base_percentage := coalesce(
      nullif(v_item->>'parts_profit_base_percentage', '')::numeric,
      40
    );
    if v_base_percentage < 0 or v_base_percentage > 100 then
      raise exception 'El porcentaje base de repuestos debe estar entre 0 y 100';
    end if;

    if exists (
      select override.repuesto_id
      from jsonb_to_recordset(
        coalesce(v_item->'part_profit_overrides', '[]'::jsonb)
      ) as override(repuesto_id uuid, percentage numeric)
      group by override.repuesto_id
      having count(*) > 1
    ) then
      raise exception 'Un repuesto no puede tener dos porcentajes de reparto';
    end if;

    if nullif(trim(coalesce(v_format.referido_por, '')), '') is null
       and jsonb_array_length(
         coalesce(v_item->'part_profit_overrides', '[]'::jsonb)
       ) > 0 then
      raise exception 'Un formato sin referido no puede repartir repuestos';
    end if;

    if exists (
      select 1
      from jsonb_to_recordset(
        coalesce(v_item->'part_profit_overrides', '[]'::jsonb)
      ) as override(repuesto_id uuid, percentage numeric)
      left join public.repuestos as repuesto
        on repuesto.id = override.repuesto_id
       and repuesto.id_repuesto = v_format.folio
       and repuesto.test_environment_id is not distinct from v_active_environment
       and repuesto.deleted_at is null
       and upper(trim(coalesce(repuesto.traido_por, ''))) = 'TALLER'
      where repuesto.id is null
         or override.percentage is null
         or override.percentage < 0
         or override.percentage > 100
    ) then
      raise exception 'Una excepcion de reparto de repuesto no es valida';
    end if;
  end loop;

  v_result := public.close_weekly_settlement(
    p_start_date, p_end_date, p_wage_fund_percentage,
    p_items, p_workers, p_total_bonus, p_deferrals
  );
  v_settlement_id := (v_result->>'id')::uuid;

  for v_item in
    select value from jsonb_array_elements(coalesce(p_items, '[]'::jsonb))
  loop
    if coalesce((v_item->>'is_advance')::boolean, false) then
      continue;
    end if;
    select * into v_format
    from public.formatos
    where id = (v_item->>'format_id')::uuid
      and test_environment_id is not distinct from v_active_environment;
    v_worker_name := nullif(trim(coalesce(v_format.referido_por, '')), '');
    v_base_percentage := coalesce(
      nullif(v_item->>'parts_profit_base_percentage', '')::numeric,
      40
    );

    for v_part in
      select *
      from public.repuestos
      where id_repuesto = v_format.folio
        and test_environment_id is not distinct from v_active_environment
        and deleted_at is null
      order by created_at
    loop
      v_percentage := 0;
      v_profit := 0;
      if upper(trim(coalesce(v_part.traido_por, ''))) = 'TALLER'
         and v_part.precio_neto_unitario is not null then
        v_profit := greatest(
          (v_part.costo_unitario - v_part.precio_neto_unitario) * v_part.cantidad,
          0
        );
        if v_worker_name is not null then
          select override.percentage into v_percentage
          from jsonb_to_recordset(
            coalesce(v_item->'part_profit_overrides', '[]'::jsonb)
          ) as override(repuesto_id uuid, percentage numeric)
          where override.repuesto_id = v_part.id
          limit 1;
          v_percentage := coalesce(v_percentage, v_base_percentage);
        end if;
      end if;
      v_commission := v_profit * (v_percentage / 100);

      insert into public.settlement_part_profit_snapshots(
        settlement_id, format_id, repuesto_id, worker_name, description,
        supplied_by, quantity, net_unit_price, final_unit_price, profit_total,
        share_percentage, worker_commission, shop_profit
      ) values (
        v_settlement_id, v_format.id, v_part.id, v_worker_name,
        v_part.descripcion, v_part.traido_por, v_part.cantidad,
        v_part.precio_neto_unitario, v_part.costo_unitario, v_profit,
        v_percentage, v_commission, v_profit - v_commission
      );
    end loop;
  end loop;

  select coalesce(sum(profit_total), 0), coalesce(sum(worker_commission), 0)
  into v_parts_profit_total, v_parts_commission_total
  from public.settlement_part_profit_snapshots
  where settlement_id = v_settlement_id
    and test_environment_id is not distinct from v_active_environment;

  update public.weekly_settlements
  set
    parts_profit_total = v_parts_profit_total,
    parts_referral_commission_total = v_parts_commission_total,
    shop_parts_profit = v_parts_profit_total - v_parts_commission_total,
    parts_profit_recorded = true
  where id = v_settlement_id
    and test_environment_id is not distinct from v_active_environment;

  update public.settlement_worker_payments as payment
  set parts_profit_commission = coalesce((
    select sum(snapshot.worker_commission)
    from public.settlement_part_profit_snapshots as snapshot
    where snapshot.settlement_id = v_settlement_id
      and snapshot.test_environment_id is not distinct from v_active_environment
      and lower(trim(snapshot.worker_name)) = lower(trim(payment.worker_name))
  ), 0)
  where payment.settlement_id = v_settlement_id
    and payment.test_environment_id is not distinct from v_active_environment;

  if exists (
    select 1
    from public.settlement_part_profit_snapshots as snapshot
    where snapshot.settlement_id = v_settlement_id
      and snapshot.test_environment_id is not distinct from v_active_environment
      and snapshot.worker_commission > 0
      and not exists (
        select 1
        from public.settlement_worker_payments as payment
        where payment.settlement_id = v_settlement_id
          and payment.test_environment_id is not distinct from v_active_environment
          and lower(trim(payment.worker_name)) = lower(trim(snapshot.worker_name))
      )
  ) then
    raise exception
      'El trabajador referido no esta disponible en la distribucion de esta liquidacion';
  end if;

  return v_result || jsonb_build_object(
    'parts_profit_total', v_parts_profit_total,
    'parts_referral_commission_total', v_parts_commission_total,
    'shop_parts_profit', v_parts_profit_total - v_parts_commission_total
  );
end;
$function$
;

