alter table repuestos add constraint "repuestos_positive_quantity" CHECK (((cantidad IS NOT NULL) AND (cantidad > 0))) NOT VALID;

alter table repuestos add constraint "repuestos_nonempty_description" CHECK ((NULLIF(TRIM(BOTH FROM descripcion), ''::text) IS NOT NULL)) NOT VALID;

alter table formatos add constraint "formatos_estado_check" CHECK ((estado = ANY (ARRAY['ACTIVO'::text, 'LISTO'::text, 'FINALIZADO'::text])));

alter table weekly_settlements add constraint "weekly_settlements_labor_goal_positive_check" CHECK (((weekly_labor_goal IS NULL) OR (weekly_labor_goal > (0)::numeric)));

alter table format_state_transitions add constraint "format_state_transitions_states_check" CHECK (((from_state = ANY (ARRAY['ACTIVO'::text, 'LISTO'::text, 'FINALIZADO'::text])) AND (to_state = ANY (ARRAY['ACTIVO'::text, 'LISTO'::text, 'FINALIZADO'::text]))));

alter table format_state_transitions add constraint "format_state_transitions_pkey" PRIMARY KEY (id);

alter table settlement_deferrals add constraint "settlement_deferrals_period_check" CHECK ((period_end >= period_start));

alter table settlement_deferrals add constraint "settlement_deferrals_reason_check" CHECK ((length(TRIM(BOTH FROM reason)) >= 5));

alter table settlement_deferrals add constraint "settlement_deferrals_pkey" PRIMARY KEY (id);

alter table formatos add constraint "formatos_ready_confirmation_check" CHECK (((estado <> 'LISTO'::text) OR ((labor_confirmed_amount IS NOT NULL) AND (labor_confirmed_at IS NOT NULL) AND (labor_confirmed_by IS NOT NULL)))) NOT VALID;

alter table offline_mutation_receipts add constraint "offline_mutation_receipts_pkey" PRIMARY KEY (operation_id);

alter table global_test_environments add constraint "global_test_environments_scope_key_key" UNIQUE (scope_key);

alter table repuestos add constraint "repuestos_precio_neto_positivo" CHECK (((precio_neto_unitario IS NULL) OR (precio_neto_unitario > (0)::numeric))) NOT VALID;

alter table repuestos add constraint "repuestos_precio_final_sobre_neto" CHECK (((precio_neto_unitario IS NULL) OR (costo_unitario >= precio_neto_unitario))) NOT VALID;


alter table settlement_part_profit_snapshots add constraint "settlement_part_snapshot_quantity_check" CHECK ((quantity > 0));

